-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[60274] = { id = 60274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading Favors", description = "Welcome, friend. \n\nI can see by your garb that you must have quite a storied history. Many unique relics befitting of one that has traveled the worlds and vanquished many foes.\n\nThere are those of us that find great value in such things, and would willingly part with our own valuables for a taste of what you may find. \n\nLet your curiosity guide you to the dark hallway across from the cookpots in the next room. Down there, you will find answers.", completion = "Ah, you must have been sent by Ta'rela. We have need of your services.\n\nTrust me, we will make it more than worth your while.", objectives = "Report to Finder Ta'sul in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60275] = { id = 60275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Enforcer Kristof", description = "WARNING!\n\nShrouded patrols have increased throughout the Ember Ward. By order of Enforcer Kristof, all who are found near the asylum will be forced to endure the Light. \n\nUse extreme caution when venturing beyond our sanctuary. Even the shadows are not safe so long as Kristof remains in power.  \n\nA reward awaits whoever is able to rid the ward of this tyrant. \n\n- Dispatcher Raluca", completion = "No tears will be shed over the loss of such a miscreant. Coin is not abundant in this ward, but take this, the owner is long gone and it will fetch a fair price.", objectives = "Find and slay Enforcer Kristof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60276] = { id = 60276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Summoner Marcelis", description = "Be advised:\n\nSummoner Marcelis and his cohorts are dabbling in dangerous magics. They are calling forth ashen elementals to ravage these Light-scorched lands. \n\nWe cannot let such acts continue. \n\nAny who can are urged to put an end to this madness. \n\n- Dispatcher Raluca", progress = "You'll get your reward when you slay Marcelis, and not a moment sooner.", completion = "Your reward, as promised.", objectives = "Find and slay Summoner Marcelis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60277] = { id = 60277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Aggregate of Doom", description = "Attention all workers: \n\nWe got ourselves a problem down in the thicket. \n\nA golem is trekking through the worksite, causing all sorts of trouble. \n\nGrab a rock and get to throwin'. The dredger that takes it out gets the rest of the day off. \n\n- Foreman Scug", completion = "You did it then? Fair enough. Now we can all get back to work.", objectives = "Find and slay the Aggregate of Doom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60278] = { id = 60278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Duke Anton", description = "Loyal Citizens of Revendreth: \n\nDuke Anton and his decrepit house are relics of noble venthyr society. \n\nHis attempts to tarnish my name are laughable at best. \n\nIt is time someone rid us of Duke Anton's presence for good.\n\nI shall offer double whatever pathetic sum he can muster. \n\nSincerely, \n\nLord Darion of House Redelav", completion = "House Redelav sure has deep pockets. But you've earned it, I suppose.", objectives = "Find and slay Duke Anton of House Briarbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60279] = { id = 60279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Pale Doom", description = "Notice to all: \n\nA lingering menace lurks in the Endmire, dangerously close to Darkhaven's border. \n\nIf alone in your travels, take care to avoid this monstrosity, lest it make you meet your true death.\n\nThose with a sense of adventure and a well-armed brigade might manage to slay this beast. If so, a reward will await you upon your return. \n\nSincerely, \n\nTaskmaster Gavril", progress = "There's no shame in turning down the bounty. Not everyone has what it takes to slay a devourer.", completion = "You have done Darkhaven a great service by slaying that beast.", objectives = "Find and slay The Pale Doom within the Endmire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60280] = { id = 60280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Lord Darion", description = "To Whom it May Concern: \n\nLord Darion of House Redelav thinks that he can buy his place in society. \n\nHe flaunts his wealth, using it to win favor of other lords and ladies. Is there no price on decency? \n\nThis is not the way the noble houses of Revendreth should conduct themselves. \n\nI implore you to find Lord Darion and help him meet his true death. \n\nThe honor of House Briarbane rests in your capable hands.\n\nWarmest Regards, \n\nDuke Anton of House Briarbane", completion = "Hopefully this means House Briarbane will stop their whining.", objectives = "Find and slay Lord Darion of House Redelav.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60281] = { id = 60281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rule 4: Make A List", description = "I've discovered that one of the Jailer's inquisitors is attempting to devise a method to track my movements.\n\nClearly, that is a problem for me... and by extension, it is a problem for you.\n\nThe inquisitor has risen to the top of my list of potential threats. In the past, I would have had to deal with him myself. But now... I have a business partner.\n\nPut an end to him, yes? And if you can, determine exactly how he intended to track me.", progress = "Have you learned anything of Inquisitor Devaki's tracking methods?", completion = "Fine work. This should keep the both of us safe from the Mawsworn. \n\nI will hold onto the sphere that you found for the purpose of study.\n\nDon't you have other matters to attend to?", objectives = "Kill Inquisitor Devaki and find out how he is trying to track Ve'nari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60283] = { id = 60283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Specter Of War: Visectus", progress = "We have conjured Visectus to lead our attack, but we need your help to prepare it properly.\n\nWe require more Anima-bound Wraps to strengthen the summons.", completion = "Thank you, {name}. Your contribution has been logged in our records for posterity to appreciate!" }
quests[60284] = { id = 60284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rule 5: Be Audacious", description = "You have proven yourself a useful associate, {class}. In thanks, I have crafted a cypher that will allow you to venture further into the Maw.\n\nBut... it is experimental in nature. You will have to test it in the field. And I have just the test in mind.\n\nCartel Ve has foolishly sent more agents into the Maw. They were captured and taken to Perdition Hold. I must know why.\n\nBreach the fortress and learn what has become of the captive brokers. Nothing is more valuable than knowledge of your enemy's plans.", progress = "What have you discovered, Maw Walker?", completion = "The Beastwarrens, you say... I wonder what they are plotting...\n\nSuch an embarrassment that they were discovered and captured in the first place. It seems Cartel Ve has become quite careless in my absence.\n\nYou have my gratitude for your assistance, as always. I will inform you when I have need of your services again.", objectives = "Investigate the increased activity within Perdition Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60285] = { id = 60285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rule 6: Concealment is Everything", description = "I have made a startling discovery, {name}. \n\nDo you recall how the captured agents of my cartel were taken to the Beastwarrens? \n\nThe Mawsworn seem to think they possess a means of tracking me. And now, strange new runes empower the Jailer's hounds.\n\nClearly, we cannot have that.\n\nThis new cypher will grant you solace from the screeching in the Beastwarrens. Brave its caverns and secure those runes for inspection.\n\nIf we are to counter their effects, I must know how they work.", progress = "The runes... you have them?", completion = "Interesting... runes that can detect brokers by using our extracted essence.\n\nLet us hope you were able to stop any further production. I will keep these for study.\n\nAt some point, you will certainly need to walk the nightmarish plains of the Beastwarrens again. My cypher will continue to allow you to do so.", objectives = "Retrieve 15 Broker Hunting Runes from The Beastwarrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60287] = { id = 60287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rule 1: Have an Escape Plan", description = "Many doomed souls suffer within the Maw. You must be careful if you do not wish to join them.\n\nYour Soulkeeper can hold a small number of souls until you return to your covenant. But that will be of little benefit if you do not survive this place yourself.\n\nThere is a substance, stygia, that is found on some creatures within the Maw. The stronger the soul, the more stygia they have.\n\nCollect some of it for me and I can fashion it into many things you will find quite useful.", progress = "I will gladly assist you in the acquisition of survival tools... provided you bring me the stygia.", completion = "You seem to have a knack for drawing the Jailer's attention.\n\nThis changes the terms of our arrangement.", objectives = "Rescue 5 souls and retrieve 60 Stygia. \n\nStronger enemies will have a higher chance to drop large amounts of Stygia. \n\nUse the Stygia to purchase a Cypher of Relocation from Ve'nari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60288] = { id = 60288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies from the Necrolords", description = "{name}, thanks to your efforts, our forces have been able to secure additional resources in our battles.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare.", sourceObjective = "Speak with Oyne Soulborn at the Bleak Redoubt in Maldraxxus for your reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[60289] = { id = 60289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rule 3: Trust is Earned", description = "Before you leave this cursed realm, there is one final task you must complete for me.\n\nThe Mawsworn regularly transfer souls to various blocks of Torghast from many different areas in the Maw.\n\nI happen to know of one such area. Place this beacon there so I may be informed when the next transfer happens.\n\nAnd if you are seen by the enemy... well, you are known for your prowess in combat, yes?", progress = "I will have opportunities for trade in the future, Maw Walker. I am certain our paths will cross again.", completion = "One of your associates was taken into Torghast? \n\nIt sounds as if he put up quite the fight. Perhaps he could also prove useful... if he were to be rescued.", objectives = "Place a Signaling Beacon in Cocyrus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60291] = { id = 60291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corpse Run", description = "There's work that needs doing 'round here. Mmmm hmmm.\n\nSpotted a big ol' carcass nearby. I aim to salvage it for parts. \n\nFigure you could come along, help me drag it to Rathan. He'd like that. Mmmm hmmm. \n\nReckon I could even carry you there and back. You don't look too big.\n\nReady to get going?", progress = "Did you bring back the carcass?", completion = "<Rathan gives Flytrap an apprehensive look.>\n\nThat's... that's great!\n\nThank you both for bringing back these resources!\n\n<Rathan flashes you a nervous smile.>", objectives = "Return the Bone Carcass to Rathan at Butcher Block.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60292] = { id = 60292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Discourse", description = "I found this scroll while you were cleansing the temple.\n\nThese are dire words, and I suspect it only gets worse. Collect more of these scrolls so I can determine just what these so-called Forsworn want.", progress = "We must defend the temple, {name}.", completion = "These words...\n\nIt is as I suspected.\n\n<Eridia stares grimly ahead.>", objectives = "Collect 6 Dark Sermons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60296] = { id = 60296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pride or Unit", description = "You have made great strides with our pride. I hope you found value and fulfillment in working with the larion.\n\nThe time to meet with Pelodis has come. You must decide whose way of life is more rewarding, and which you would prefer to pursue.", progress = "The pack has welcomed you, {name}. I hope that you feel it.", completion = "It is done.", objectives = "Meet with Pelodis and Nemea, then pick a side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60313] = { id = 60313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dredhollow", description = "That was a narrow escape.\n\nBut I believe this presents an opportunity to finally turn the tide of this strife and defeat the Fearstalker. Meet me at Dredhollow: the abandoned hunting lodge of the Fearstalker.  \n\nWe must take separate paths. The Fearstalker will soon be after us again.", completion = "I am glad you made it here alive.\n\nGeneral Draven has informed me of a plan that might just work.", objectives = "Meet the Accuser at Dredhollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60315] = { id = 60315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Gorgebeak", description = "Thief! Pilferer! Menace!\n\nThe insidious menace known as Gorgebeak threatens our harvest of ambrosi for tribute to our great Archon. She must be stopped!\n\nIf any are willing to take on this foul fowl, I have tracked her nest to the western edges of Firstborne's Bounty. Proof of her demise shall be amply rewarded.\n\n--Gerdus", progress = "What business have you with this simple tender?", completion = "Our harvest is saved! Oh thank you, brave adventurer, our tribute may be saved yet!", objectives = "Collect Gorgebeak's Bill for Gerdus in Firstborne's Bounty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60316] = { id = 60316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Altered Sentinel", description = "Praetor broken! At Aspirant's Crucible. Attacking everybody!\n\nSomething wrong. Maybe changed?\n\nSimo not know how to fix. Tried everything!\n\nMust destroy!", completion = "Oh! Broke praetor is gone? Sad. So sad. But thank you-hoo!", objectives = "Destroy the Altered Sentinel for Forgehand Simo in Aspirant's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60337] = { id = 60337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pupa Trooper" }
quests[60338] = { id = 60338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Ardenweald", description = "The warning you received from the Primus needs to reach the Winter Queen of Ardenweald, {name}. The Eternal Ones must stand together against the coming darkness.\n\nThe Winter Queen oversees the cycle between Death and Life. In her forest slumber ancient spirits of nature that must be reborn.\n\nI fear the anima drought will have taken an especially grim toll upon her realm. \n\nThe night fae can lead you to the Queen. Bring her this message, and she will know what needs to be done.", completion = "We haven't seen anyone come through the gateway in a very long time! Certainly not someone like you.\n\nWhat brings you to Ardenweald?", objectives = "Travel to Ardenweald and find someone to take you to the Winter Queen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60339] = { id = 60339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ember Court", description = "Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker.\n\nBe sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court.\n\nRemember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy!\n\nTalk to Lady Ilinca if you have any questions about guests.\n\nOnce everything's ready, talk to me and I'll open the court!", progress = "I can't wait to see who attends today's court!", completion = "Now THAT was a court to remember!\n\nHow are you going to top that next week?", objectives = "Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60340] = { id = 60340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hands on Approach", description = "When I was imprisoned in the Etheric Vault, the anima scroungers would come to steal what little strength my soul still had. I swore I'd have revenge upon them should I ever escape.\n\nNow, with my blade hands... it's time for my revenge! \n\nI've seen anima scroungers near the House of Constructs. I want their leader dead and the anima they took from me recovered!", progress = "Did you kill them all?", completion = "Guillotine can be vicious, but sometimes that's exactly what the situation demands.", objectives = "Slay Wurtzog Soultap and recover 12 anima traces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60341] = { id = 60341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First on the Agenda", description = "Let's make a deal, {name}. I'll seek out the Winter Queen on your behalf if you complete a few of my duties in my stead. The Queen isn't the only one who's been kept busy by the drought!\n\nFirst, you're going to help my fellow fae here with their spriggan problem. Boot their leader off that poor moth! Featherlight will tell you where to go after that. \n\nWe'll reunite in Tirna Vaal if you survive.\n\nOh, and I would stay on the path if I were you. Ardenweald can be dangerous for the unwary!", progress = "Not bad! Not bad at all!", completion = "If you can handle the spriggans, then perhaps I can give you some of the more interesting items on Lady Moonberry's agenda. Excellent!", objectives = "Slay Mothbane the Mighty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60342] = { id = 60342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut 'Em Down to Size", description = "Idle hands are a wasted opportunity. I need to keep my hands busy, or else these blades wouldn't be worth anything!\n\nI hear there's a devourer in Revendreth that's as tall as a house. Let's show the other constructs a thing or two by taking that monster out!", completion = "Good work, both of you! \n\nGuillotine's efforts have not gone unnoticed. I've seen the others redouble their efforts to follow her example.\n\nThank you both, again.", objectives = "Slay Charthox in the Dredgewood of Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60343] = { id = 60343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Orgrimmar", description = "The warchief will be waiting for our mission report from Exile's Reach. I must deliver it at once.\n\nFor now, Cork Fizzlepop will show you around the city. Orgrimmar has much to offer, so explore it as you see fit.\n\nI'll send for you once I've given my report to the warchief.", completion = "Hey, {name}! Long time no see, am I right?\n\nWarlord Grimaxe asked me to show you the sights. Let's go!", objectives = "Meet with Cork Fizzlepop at the city gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60344] = { id = 60344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Your Way", description = "Orgrimmar's a big city. Way too big to explore on foot. Warlord Grimaxe has arranged for you to receive a mount to help you get around.\n\nShe said to speak with Rohaka at the stables... but I can't seem to remember the way there.\n\nDon't worry, {name}! All we need to do is ask a guard for directions. If you ever need help finding something, the city guards will show you where to go.\n\nLet's ask a nearby guard for directions to the stable master. Then we can be on our way!", progress = "Welcome to the stables, {class}. I've been expecting you.", completion = "Warlord Grimaxe instructed me to give you a mount, but there's something we need to do first.", objectives = "Speak with Rohaka Tuskmaul at the stables.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60345] = { id = 60345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "License to Ride", description = "Warlord Grimaxe told me you'd be coming to the stables to pick up your mount.\n\nBut before you go charging into battle, you'll need to learn how to ride it first.\n\nSpeak with Kildar when you're ready to learn how to ride.", completion = "Now that you've learned the basics, feel free to return any time you want to advance your riding skills or purchase additional mounts!", objectives = "Speak with Kildar to learn the Apprentice Riding skill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60346] = { id = 60346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Telotha Pinegrove to learn more about specializations!", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, {name}.\n\nFeel free to test out your new abilities on the training dummies outside on the upper level of the building.", objectives = "Speak with Telotha Pinegrove to learn about combat specializations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60347] = { id = 60347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Tamanji to learn more about specializations!", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, {name}.\n\nFeel free to test out your new abilities on the training dummies outside on the upper level of the building.", objectives = "Speak with Tamanji to learn about combat specializations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
