quests[60357] = { id = 60357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Gormok Ogrefist to learn more about specializations!", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, {name}.\n\nFeel free to test out your new abilities on the training dummies outside on the upper level of the building.", objectives = "Speak with Gormok Ogrefist to learn about combat specializations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60358] = { id = 60358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gildenite Grab", description = "Took our gildenite! Stole it! Stole it and took it away!\n\n<Sika's feathers ruffle.>\n\nNeed it, need it to make armor! Weapons!\n\nCan't make armor without gildenite!\n\n<Sika moves her arms as if explaining how armor is made.>\n\nYou understand? Yes? Why you still here?", objectives = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60359] = { id = 60359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Is Where the Hearth Is", description = "I don't know about you, but I'm in the mood for some good ol' fashioned recreation!\n\nWhy don't we head over to The Wyvern's Tail and cool off with a few pints of Cobo Cola?\n\nWhile we're there, speak with Innkeeper Nufa to make The Wyvern's Tail your new home. That way, if you ever find yourself stranded without a flight master nearby, you can use your hearthstone to return to the inn.\n\nNot only is it faster than a wyvern, but you'll save yourself some dough in the process!", progress = "How can I help you today, {class}? Are you looking for a place to stay?", completion = "As long as The Wyvern's Tail is your home, you can find a warm fire here when you return.", objectives = "Speak with Innkeeper Nufa to make The Wyvern's Tail your home.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60360] = { id = 60360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Urgent Meeting", description = "I've been looking for you all over Orgrimmar, {name}.\n\nWarlord Grimaxe has delivered her mission report to the warchief. The Horde has need of you once again.\n\nI was ordered to find you and deliver the message without delay. It has been an honor to fight alongside you, {name}.\n\nLok-tar ogar!", completion = "Good, you're here. The warchief wishes to speak with you.", objectives = "Speak with Warlord Breka Grimaxe at Grommash Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60361] = { id = 60361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth: Mission Statement", description = "The warchief has requested to meet with you in person.\n\nLady Sylvanas was impressed with the prowess and courage you displayed during our mission to Exile's Reach. \n\nNow that you've arrived, I will make the introduction.", completion = "The Dark Lady has placed her trust in us. We will not fail her, {name}.", objectives = "Attend the war meeting in Grommash Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60362] = { id = 60362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blank", description = "Kul Tiras is the greatest naval power in Azeroth, and a former ally. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was defeated at Theramore.\n\nMany have criticized Jaina's decision that day, saying she believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father.\n\nPerhaps she feels the time has come to atone for this.\n\nLoath as I am to put Jaina in harm's way... Kul Tiras must join the Alliance.\n\nGood luck.", objectives = "Speak with Lady Jaina Proudmoore in Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60363] = { id = 60363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gildenite Grab", objectives = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60364] = { id = 60364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gildenite Grab", description = "Our allies in Bastion are in possession of a special ore known as gildenite. A golden metal used for many things in their lands, it is also useful to us.\n\nOnce upon a time, we would have traded for it. Now, we have little to trade, and they have little to give.\n\nYet it is a necessary component to focus our magics, capable of harnessing magical energy and amplifying it.\n\nShould you come across any in your travels, liberate it, and return it to me. I shall use what we need, and share the remainder.", objectives = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60365] = { id = 60365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gildenite Grab", description = "The golden ore known as gildenite is found only in Bastion. Used to make many of their own armors, it is useful to us all. We harden our own armors and weapons with it, and it holds magical charge well.\n\nOur stores are nearly depleted, and we have little to trade, but our needs are great.\n\nLet us reflect. \n\nIn Bastion, there are those that have turned their backs on their own people.\n\nWe may relieve these deceivers of their gildenite without remorse.", objectives = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60366] = { id = 60366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Darkwing", description = "The Cloudfeather matriarch, Darkwing, has fallen to a great and terrible sickness. She has grown aggressive, dominating her children and driving them to violence.\n\nDarkwing must be slain if her flock is to ever return to the Archon's grace.\n\nPlease use the attached whistle to call her to her nest. I shall consider one of her crown feathers sufficient proof of the deed.\n\n--Eumelia, Stable Master", progress = "Until Darkwing rests at last I fear her brood will know no peace.", completion = "You have my gratitude for restoring balance to these fascinating creatures. We all have our part to play.", objectives = "Collect an Umbral Plume from Darkwing in Greatwing Roost for Eumelia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60367] = { id = 60367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Crossing" }
quests[60369] = { id = 60369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wealth of Wealdwood", description = "The shapers of our lands cultivate a very special form of wood we call wealdwood.\n\nIt contains the essence of Ardenweald, of the plants and animals that make up our soil and our air. It can be enchanted with powerful magics, and it will not burn.\n\nIt is the basis of our arms and armor, and in these dark days, it is a target of our enemies.\n\nThey steal and hoard it, out there in the wilds. \n\nFind them, and return our treasures to us.", objectives = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60370] = { id = 60370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wealth of Wealdwood", description = "In Ardenweald, the shapers form boughs into a magical form of wood. Wealdwood, an enchanted substance used for many sorcerous purposes, is a key component in our rituals.\n\nWithout it, our magics pale in comparison to those of our enemies.\n\nYet in these times, Ardenweald is beset by many foes. They steal the supplies of the Night Fae and scurry off into the dark places.\n\nTravel to those places, and return to us once you have brought atonement to these vile creatures.", objectives = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60371] = { id = 60371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wealth of Wealdwood", objectives = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60372] = { id = 60372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wealth of Wealdwood", description = "Ardenweald in trouble! We in trouble too! No Ardenweald, no wealdwood.\n\nwealdwood magical, help us make many thing.\n\nYou find some? Bring to Sika? Yes? Hoo?\n\nYes. \n\n<Sika writes your name on a scroll and underlines it twice, then shows it to you.>\n\nSee?", objectives = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60373] = { id = 60373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Source of Sorrowvine", description = "There is a dark, evil vine that grows in Revendreth, known as sorrowvine.\n\nThey say it feeds off of the anguish of the souls as they are broken.\n\nRegardless of its origins, it is used in many of our potions and spells. It contains a powerful magic, likely a product of its origin.\n\nRevendreth has little opportunity to trade with us these days. Should you find any of these vines, I will gladly accept them.", objectives = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60374] = { id = 60374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonemetal Bonanza", description = "The denizens of Maldraxxus are used to a life of battle, and in doing so, find themselves in possession of so very many bones.\n\nThey form their armors out of a cultivated form of bone we call bonemetal. Harder than most metals, yet pliable, it can be forged into a variety of shapes without losing its strength.\n\nWe have many uses for it, both as a means of attachment, and when ground up, as a reagent.\n\nWe cannot ask them for resources now, but if you find any, I would use it.", objectives = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60375] = { id = 60375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonemetal Bonanza", description = "Maldraxxus no longer answers our calls, and the houses are in disarray.\n\nYet we have need of them. Once, they supplied us with bonemetal, a strong yet malleable material useful for many armors.\n\nThere are those in Maldraxxus that hoard the material, seeking to profit from the chaos.\n\nThey must atone for these sins.", objectives = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60376] = { id = 60376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonemetal Bonanza", description = "Ksh-ksh-ksh... you are needed.\n\nSo many betrayers in our lands, many deaths, much armor destroyed. \n\nNeed to rebuild.\n\nThe eyes have shown me stores of bonemetal, hoarded by our foes.\n\nBring them to me.", objectives = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60377] = { id = 60377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonemetal Bonanza", description = "<Sika is studying a scroll.>\n\nNo bonemetal! Again, out of bonemetal!\n\n<Sika throws a pile of scrolls into the air.>\n\nHoo! Where you come from?\n\nOh, OH. bonemetal! You get? Get from Maldraxxus. Help us out!\n\n<Sika points in the direction of Maldraxxus.>\n\nThat way!", objectives = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60378] = { id = 60378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Source of Sorrowvine", description = "Sorrowvine grows only here, in the lowlands of Revendreth. It has power contained within the leaves and seeds, perhaps a byproduct of the cleansing of sins.\n\nWe use it for many things, from potions to venoms. It is a versatile reagent.\n\nOur stores are low, and we have little ability to forage these days with the forces of our enemies bearing down on us.\n\nAs you travel our lands, should you come upon any, we would make good use of it.", objectives = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60379] = { id = 60379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Source of Sorrowvine", description = "Kshh... need you today. Stores of sorrowvine getting low, need it for our venoms.\n\nRevendreth does not answer our calls. The eyes show me conflict and strife in their lands.\n\nThis matters little to us.\n\nShh... travel there, find their vines, return to me.", objectives = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60380] = { id = 60380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Source of Sorrowvine", description = "Need sorrowvine! Please help!\n\nRevendreth not sending us supplies, not answering Sika! Can't make potions now. What we do?\n\n<Sika seems to have just remembered that you were there.>\n\nYou go! \n\n<Sika pushes you.> \n\nGo go!", objectives = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60381] = { id = 60381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Ardenweald", description = "Today, we must turn our gaze inward. We are beset by foes here, in Ardenweald, from all sides.\n\nTravel our lands, weapon in hand, and bring hope and victory with you. Bring aid to those in need, and remind them that we are here for them, and Ardenweald will not fall.\n\nRemind them that our great purpose will be fulfilled, and we will not let the groves wither.\n\nYou, Maw Walker, will unite us today.", progress = "Have you brought hope and faith to our people today?", completion = "Our bonds are stronger, our roots grow deeper, due to your actions this day. We will hold strong against the onset of foes that plague us, as groves weave together in defense, thanks to you.", objectives = "Complete 3 World Quests in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60382] = { id = 60382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Revendreth", description = "We do not turn out backs on our allies, even when we face darkness here in Ardenweald.\n\nIn Revendreth, they battle against the forces of Sire Denathrius, who has proven himself a false leader.\n\nWe cannot allow those that make Sinfall their home to lose hope.\n\nTravel to Revendreth and supply aid to them. Show them that we will not let them falter, that we are stronger together.", progress = "How goes the battle in Revendreth?", completion = "As we aid our allies, we all remember the bonds that forge us together in our world. Together, we will overcome, and only together, will the Shadowlands function once more.", objectives = "Complete 3 World Quests in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60383] = { id = 60383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Maldraxxus", description = "Maldraxxus defends us from forces that threaten the Shadowlands, or at least, they once did.\n\nNow they are plagued by infighting and an imbalance in power.\n\nWe have few allies there, but those that remain, we must maintain.\n\nGo there, give them aid, and help them reunite the houses such that the armies of the undying may defend us once more.\n\nWithout them, we are but one invasion from complete annihilation.", progress = "Have you aided the forces of Maldraxxus?", completion = "We are now one step closer to reforging the army that will defend our worlds. This is a good thing you have done today.", objectives = "Complete 3 World Quests in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60384] = { id = 60384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Bastion", description = "The denizens of Bastion have long served the Shadowlands with faith and honor. Without them, souls would not arrive for us to nurture, and our lands would wither and die.\n\nWe cannot allow them to fall, for without Bastion, we are lost.\n\nTravel to the golden fields, weapon in hand, and provide aid to our besieged allies. We will show them that in these dark times, they are not alone.", progress = "Have you aided Bastion today?", completion = "Even in dark times, we cannot allow others to be alone with their troubles. It is only when we stand together that the Shadowlands can become whole again.", objectives = "Complete 3 World Quests in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60385] = { id = 60385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training in Revendreth", description = "The dark lands of Revendreth, ruled over by the traitor Denathrius, pose a great risk to us, and a great opportunity for training.\n\nCome here, trainee! Today, you hunt with the Maw Walker. Should you return to me, we will celebrate, with a hunt.\n\nFor tomorrow, we hunt.", completion = "I smell a group of successful hunters, good. Each successful hunt brings us one step closer to a trained hunting pack.", objectives = "Complete 3 World Quests in Revendreth with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60386] = { id = 60386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training in Maldraxxus", description = "The forces of Maldraxxus are some of the most highly trained and well-regimented in all of the Shadowlands. Once, they defended us all, now we must fend for ourselves.\n\nThere is little better place for our trainees to gain real combat and strategy experience than on their blood-soaked battlefields.\n\nTake this one with you on your travels today, so that they may see what real combat looks like.", progress = "Do you return with a trainee, or a coward?", completion = "There is little better than real combat experience to train our next generation of hunters. Thank you for keeping this one alive.", objectives = "Complete 3 World Quests in Maldraxxus with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60387] = { id = 60387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training in Bastion", description = "Our hunters do not have the time for proper training, and so we must train them in the field.\n\nOur allies in Bastion are in desperate need of support, and I wish one of the trainees to accompany you in this endeavor.\n\nDo you hear that, trainee? Today, you accompany the Maw Walker!\n\nMaw Walker, do not go easy on this one.", progress = "I hope that today's trainee survived the trip, but I am not overly confident.", completion = "Good, a tired trainee is a trainee that has seen combat and gained many experiences. You have done well with this one.", objectives = "Complete 3 World Quests in Bastion with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60388] = { id = 60388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training Our Forces", description = "Get up, trainee, you must get up!\n\nLook at this one! Needs much more training before we stand a fighting chance against our enemies. \n\nWe have precious little time to build combat prowess these days, with so many foes at our backs.\n\nTake this one with you today, show them the ways of battle, and keep them safe from overwhelming odds. It is the only way we will make enough progress.", progress = "How goes the training?", completion = "You have done well, we will allow them to rest a moment. Today they have learned that even in the calmest meadow, there is always danger.", objectives = "Complete 3 World Quests in Ardenweald with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60389] = { id = 60389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Ardenweald", description = "Ay there, ya got a moment?\n\nLotta things going on down in Ardenweald. Bad stuff, bugs and things. Look delicious, but probably give me ol' stomach a nasty one.\n\nWe're lookin' pretty solid here today, ya see? Probably could use a hand down there. Maybe they give us a hand in return, see? \n\nDo I gotta spell it out for you? Get on over there, ya big goof.", completion = "Ain't never been a friend to no Night Fae, but maybe it's about time we went lookin' for more allies. Gotta start somewhere, I suppose.", objectives = "Complete 3 World Quests in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60390] = { id = 60390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Ardenweald", description = "We are attacked by enemies on all sides, Maw Walker. \n\nAnd Ardenweald faces a similar threat.\n\nIt is in our best strategic interests to forge lasting alliances with those outside of Maldraxxus. Though we may be under assault, we are still the strongest military might in the Shadowlands. Under our protection, they will thrive and grow, and in turn, provide us with aid in our times of need.\n\nTogether, we are strong. This is the doctrine of the phalanx, and it will be ours as well.", progress = "Have you secured allies in Ardenweald?", completion = "Stability in Ardenweald will serve us as we move against the enemy. This was a solid strategic choice, Maw Walker.", objectives = "Complete 3 World Quests in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60391] = { id = 60391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Ardenweald", description = "Ardenweald has long been one of our closest companions in the shepherding and nurturing of souls. Now they are beset by many foes, and we will not allow them to fall!\n\nMake haste to their forested lands, and with the blessing of the Archon upon you, serve a glorious purpose. Stand with them in their time of need, a gilded shield, a reminder that they are not alone!\n\nBastion stands with them, and with us, they will never falter!", progress = "Have you served in Ardenweald today?", completion = "Today we are blessed that the Maw Walker has brought our divine purpose to Ardenweald! Our allies rejoice in your victories!", objectives = "Complete 3 World Quests in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60392] = { id = 60392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Bastion", description = "In our own golden hills, evil abounds. We will not allow it to take root and fester!\n\nRaise your voice, Maw Walker, and shout to the foes of Bastion! We are coming for them!\n\nWith haste, now, seek out those in need of your might. Bring the sharpened blade of faith to bear against doubt and uncertainty. Crush despair with a gilded fist, and let it know the vengeance of the Archon!\n\nFor Bastion!", progress = "Do the hills echo with the cries of your victories, Maw Walker?", completion = "The hills speak of your faith and honor, our forces radiate with each victory! Glory to Bastion, glory to the Archon, glory to the Maw Walker!", objectives = "Complete 3 World Quests in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60393] = { id = 60393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Bastion", description = "The kyrians of Bastion serve a unique purpose in the Shadowlands, and without them we will be unable to replenish our forces. Should we wish to stand triumphant in Maldraxxus, we must extend some of our might to aid them.\n\nTravel to Bastion and provide support, so as to stabilize their situation. In doing so, we will secure the future of our armies and cut off the supply to our enemies.\n\nWar is not always fought on the battlefield, but often in the means of replenishment.", progress = "Have you secured the situation in Bastion?", completion = "We are one step closer to returning our supply of souls to a functioning form, Maw Walker. This is an important advancement in the war for Maldraxxus.", objectives = "Complete 3 World Quests in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60394] = { id = 60394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Bastion", description = "If'n the kyrians of Bastion don't get souls to the Shadowlands, we got no one to join up, and no anima to gain in them sinstones. Be in a bad place, you know, now and in the future, if things ever bother to get better.\n\nWe got things figured out here today. Head on over to them golden hills of Bastion and give 'em a hand. Bet they pay us back some day. They're all about honor an' stuff.\n\n<Rendle wipes his nose loudly.>", completion = "Always wanted to eat a steward, never got the chance to. Really wonder what they taste like. \n\nWas a good thing you did for them, anyway. Just got some idle musings I do.", objectives = "Complete 3 World Quests in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60395] = { id = 60395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Maldraxxus", description = "In the fetid wastes of Maldraxxus, we yet find allies. Their sacred duty, to defend the Shadowlands, has not been forgotten by all.\n\nWe must take flight, now, to stand side by side with our bone-bound brethren. Shoulder to shoulder, hand in hand, we will push back those that would sow chaos and discord.\n\nA spear of gold and bone we will form! And thrust it into the heart of evil!\n\nGo now, Maw Walker, as the tip of the spear, to glorious battle!", progress = "Have you pierced the heart of evil in Maldraxxus?", completion = "Glorious! The gilded halls of Bastion stand firm with our allies in Maldraxxus, may they never wane in their battle for righteousness!", objectives = "Complete 3 World Quests in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60396] = { id = 60396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Maldraxxus", description = "The allies we have here in Maldraxxus may be few, but we cannot turn our backs on them. Every hand we pull out of darkness and into our fold, is a hand that can hold a weapon or wand.\n\nWalk our lands, find those seeking aid, and provide it. Crush our enemies, and show them that we are at once everywhere. Make them fear you.\n\nFear is the seed that breeds doubt, and doubt is the root that crumbles empires.", progress = "How goes the battle?", completion = "Our rival houses will think twice before stepping foot outside of their strongholds again. Blood and glory to you, Maw Walker.", objectives = "Complete 3 World Quests in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60397] = { id = 60397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Maldraxxus", description = "Once was a time that those bony lot in Maldraxxus were the defenders o' all of us here in the Shadowlands. Now they spend their time destroyin' what little they got left.\n\nAll's I know is that if things keep up like this, one big ol' swath of devourers could sweep in and wipe us all out.\n\nGet over there and help them good ones keep the peace, maybe they help us out some day, too.", completion = "Maybe things get a bit more stable down there in Maldraxxus, now. Would do us all a lot o' good.", objectives = "Complete 3 World Quests in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60398] = { id = 60398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Revendreth", description = "Our allies in Revendreth are all that stem the tide of Denathrius's forces from overtaking the rest of the Shadowlands. \n\nOnce, we would be charged with righting this wrong, but our armies have dwindled with the actions of our rival houses.\n\nToday, you will be the messenger from Maldraxxus, carrying a message of justice in the name of the great cycle of which we all take part.\n\nIt is your Primus-given duty to aid Sinfall against those that seek to break the cycle.", progress = "Have you broken the forces of Denathrius?", completion = "With your aid, we have once again been able to perform our sacred duties in defense of the Shadowlands. Little by little, we right the wrongs that have sent us awry, that the cycle can begin anew.", objectives = "Complete 3 World Quests in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60399] = { id = 60399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Revendreth", description = "Oi there, got somethin' for you to do today.\n\nLots of problems outside of Sinfall, there are. Big problems, little problems, all sorts of problems.\n\nWe're not gonna make much headway against Denathrius with his lot at our heels all the time, ay?\n\nGet out there an' get some muck on your boots.", progress = "What do ya want?", completion = "Ya did a good thing today, an' we're safer for it. Never been one to give a compliment, me, but today I gotta say ya did a good one.", objectives = "Complete 3 World Quests in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60400] = { id = 60400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Revendreth", description = "Take flight to Revendreth, where those that are loyal to the Shadowlands are under siege from the forces of Sire Denathrius.\n\nWe cannot allow them to fall. Without the aid of Sinfall, the forces of Revendreth will grow unchecked, and their dark alliance with the Jailer will threaten us all.\n\nWe of Bastion will not allow this to happen! Raise your swords, ready your shields, take wing and bring the glory of Bastion to Revendreth!", completion = "Even those that are far from our lands are necessary allies in these dark times. With faith and honor we will serve them, and the Shadowlands, until evil clips our wings!", objectives = "Complete 3 World Quests in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60401] = { id = 60401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training in Ardenweald", description = "I have another trainee for you to look after, they need some training on the battlefield. Take them out to, oh, let's say Ardenweald. \n\n<Sakaa waves her hand vaguely in the direction of Ardenweald.>\n\nPlenty of things to maim over there, maybe they learn a thing or two about wood.\n\n<Sakaa smirks.>", completion = "Oh, well, good job carting this one around, then. Hope they didn't give you any trouble.\n\nMaybe a little trouble would be acceptable.", objectives = "Complete 3 World Quests in Ardenweald with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60402] = { id = 60402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training in Ardenweald", description = "Look at this lot! Bones and gristle, all of them. Need some meat on their bones and some training in their heads.\n\nTake this trainee out and get them some real combat experience.\n\nArdenweald's a good spot, plenty of things to fight there. Learn some new tactics, get them used to the chaos of battle, all that stuff.", progress = "You back already?", completion = "Good, good, I can already see this one's learned a thing or two today. I'll take it from here.", objectives = "Complete 3 World Quests in Ardenweald with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60403] = { id = 60403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training in Ardenweald", description = "It is our great duty to take our aspiring warriors and train them in combat. \n\nToday, this is your trainee. Take them to Ardenweald, show them what it means to be in the glorious service of the Archon. Defend our allies, and bring faith to their lands.\n\nTeach them the ways of battle and honor.", progress = "How fares the training?", completion = "You have returned with your charge intact, most benevolent. Carry the lessons of the teacher with you.", objectives = "Complete 3 World Quests in Ardenweald with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60404] = { id = 60404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training Our Forces", description = "What better place to stretch our wings than right here on our own fields?\n\nTake one of our trainees out with you today, show them the ways of combat in Bastion against the growing threats we face here.\n\nPart of their training will be courage when facing off against those they thought their brethren.\n\nIt has been known to break hearts and ranks before.", progress = "How fares your heart today?", completion = "Let this one rest, now. Facing threats from within, let alone against ones you once considered kin and ally, can take a mighty toll.", objectives = "Complete 3 World Quests in Bastion with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60405] = { id = 60405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training in Bastion", description = "Useless minions, the lot of them. All of this fodder needs to get trained.\n\nHere, take this one with you today. Get them away from me, go to... Bastion. Yeah, Bastion, far away from me.\n\nPlenty of things to test them against, there. \n\nIf you get them killed, I don't want to hear it.", progress = "Any luck with this sad lot?", completion = "Well well well, kind of surprised you managed to make it back with your trainee intact. Guess you're a better instructor than I gave you credit for. Going to keep that in mind.", objectives = "Complete 3 World Quests in Bastion with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60406] = { id = 60406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training in Bastion", description = "I have yet another minion, er, recruit that needs training.\n\nTake them on out to the fertile fields of Bastion. There is plenty to learn over there that they won't find around these parts, perhaps it will help them grow into a better soldier. \n\nMaybe you pick up some new tricks while you're out there, too.", completion = "Thank you for showing them around today. There's plenty to learn still, though.", objectives = "Complete 3 World Quests in Bastion with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60407] = { id = 60407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training in Maldraxxus", description = "Our aspiring warriors must be trained in the thick of battle, in the harshest conditions, for wars do not happen lightly, and never will it give them pause for breath.\n\nTake this one to Maldraxxus--the heart of the armies of the Shadowlands resides there. It is a land in chaos and turmoil, filled with fallen champions and gladiators.\n\nThere, they will face true challenges, and return with great knowledge.", progress = "Has your trainee survived the fields of battle?", completion = "Ah, good, you returned with your trainee intact. Truthfully, each time we send them on such an errand, it is a game of chance. It is good you were with them.", objectives = "Complete 3 World Quests in Maldraxxus with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60408] = { id = 60408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training Our Forces", description = "Our armies are nothing without some combat training, but every time we send them out, they come back as a pile of bones and meat.\n\nTake a trainee out and pit them against the forces of the other houses. Just don't get them killed, alright? Not all the way killed. A little killed is fine.", progress = "Any luck out there?", completion = "By my bones, you came back and your trainee isn't a pile of mush. Can't believe my eye sockets.", objectives = "Complete 3 World Quests in Maldraxxus with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60409] = { id = 60409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training in Maldraxxus", description = "Another trainee needs some looking after, if you don't mind.\n\nMaldraxxus is a place of constant battle, and probably the best place to take them. They've got to learn about war and strategy and, you know, all that.\n\nJust throw them in the arena or something. 'Sink or swim' is an effective training strategy.", progress = "Could really go for a nap I could.", completion = "Your trainee's looking a little roughed up, but none the worse for wear. Probably learned a thing or two.", objectives = "Complete 3 World Quests in Maldraxxus with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60410] = { id = 60410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training Our Forces", description = "I have yet more troops for you to train, and there are plenty of things to do right here in our domain. \n\nTake them out and give them a good, solid, and probably bloody taste of what we're up against.\n\nNow, if you get them killed? That's none of my business.\n\n<Sakaa sips a thick and sweet-smelling beverage.>", progress = "Did you manage to bring them back alive?", completion = "Well, it looks like you drilled some good experience into this one today. Only a few broken bones!", objectives = "Complete 3 World Quests in Revendreth with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60411] = { id = 60411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training in Revendreth", description = "Lousy, useless, bunch of bones. This army's less of an army than it is a bunch of dead meat walking.\n\nDo me a favor, take out this trainee and head over to Revendreth. Give them some good battle training against some of our enemies, a little taste of strategy and tactics and maybe getting hit in the face with a little magic.\n\nWon't do us any good unless we find a way to train them that doesn't end up in a bunch of dead minions.", progress = "Well? You bring back a pile of bones or a trainee?", completion = "Looks like this one's got a bit more in the head now, maybe they'll survive beyond a battle now.", objectives = "Complete 3 World Quests in Revendreth with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60412] = { id = 60412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training in Revendreth", description = "A trainee is in need of your guiding hand.\n\nTake them to Revendreth, where you will find the armies of Denathrius thirsting for our demise. Wade in to battle with them against our mighty foes.\n\nReturn victorious, as their shield and mentor, so that our armies will be bolstered this day.", completion = "Another glorious day of training in the name of the Archon! We will let this one rest now, to train another day.", objectives = "Complete 3 World Quests in Revendreth with your trainee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60414] = { id = 60414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Resources", description = "The Brokers are odd characters, but useful. They can find many things across the vast realms of the Shadowlands that we cannot. \n\nWe have relied upon them to bring us useful materials for many years, but these days, we have little to trade.\n\nThey value a currency of their own making, coins of brokerage, as a general means of trade.\n\nIf you find any in your travels, I would appreciate a handful, as it would allow me to procure some rare and necessary items.", progress = "Have you found any coins?", completion = "Oh, this is quite a find. These will allow me to procure some rather rare ingredients and materials, and with them, we may turn the tide against our foes. Well done.", objectives = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60415] = { id = 60415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Resources", description = "Hello! Yes! Hello.\n\nBrokers, you know them? \n\n<Sika does her best attempt at looking like a broker. It is not convincing.>\n\nTrade many things with us. Things we no get. Things we want.\n\nNeed coins. Clink clink!\n\n<Sika makes a circle with her finger feathers.>\n\nFind them everywhere, bring them to Sika!", progress = "Bring coins to Sika? Need trade with brokers. You know this?", completion = "Coins! Coins for Sika! Happy Sika, happy friends. Can buy many things, strange things, you no understand, is ok.\n\n<Sika takes the coins and waves at you.>", objectives = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60416] = { id = 60416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Resources", description = "Kh-kh-kh... the brokers, they go to many places. Many places we cannot. The eyes cannot follow them.\n\nFind many secrets, they do. Bring us supplies, strange and rare.\n\nNeed things to trade. Need broker coins.\n\nThey trade with all. Find coins in all lands. Slay those that hold them, bring the coins to me. \n\nYou may eat their corpses, I will not judge. Just need coins.", progress = "Bring me coins? Coins for brokers. Many uses. You see?", completion = "The clink of the coins is the sound of secrets being revealed. Many uses, many things I will purchase. More powerful will we become, due to this. A good find.", objectives = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60417] = { id = 60417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Resources", description = "The brokers are an enigmatic group. We know little about them, save that they can travel to many lands in the Shadowlands that we cannot. How they do this, we are not sure.\n\nThey are willing partners in trade, though, and through them we have acquired many rare and valuable resources that cannot be found elsewhere.\n\nThey hold in high regard a currency of their own creation, you may find such coins in your travels. \n\nI will gladly take them off of your hands to bolster our supplies.", progress = "Have you found any of the broker's coins?", completion = "This small handful of coins will purchase many things of use to us. I will contact them directly.\n\nThank you, Maw Walker.", objectives = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60418] = { id = 60418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Bastion", description = "Our allies in Bastion are absolutely necessary for the Shadowlands to function at all. They alone can bring us the souls we need to keep the cycle moving. \n\nIf they fall to darkness, it's only a matter of time before we, too, dwindle and fade.\n\nThey are beset by all manner of problems. We have to get over there and help them!", progress = "How are the Kyrians?", completion = "I've gotten word from our Kyrian allies that you did them a great service! Thank you!", objectives = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60419] = { id = 60419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troubles at Home", description = "They say that all of the Shadowlands is a stage, and right now, I think we're in a tragedy! \n\nAll throughout Ardenweald, we are under attack. They seek our anima and the souls that we protect.\n\nIf the cycle stops here, so many great souls will be lost... forever.\n\nThere's no time to waste, we need your help! Defend Ardenweald!", progress = "Are things improving in the glades?", completion = "I've heard many tales of your greatness, the Winter Queen is quite pleased! \n\nPlease take this, and keep up the fight!", objectives = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60420] = { id = 60420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Maldraxxus", description = "I'm glad you're here! We've got some problems in Maldraxxus.\n\nThe forces of Maldraxxus are the defenders of the Shadowlands. They've always managed to balance one another out, like actors on a stage, never stealing too much of the spotlight. \n\nBut now, some of the houses have overthrown the balance, and seek to conquer the rest of us!\n\nOur allies there need our help! Aid them however you can.", progress = "Are things improving in Maldraxxus?", completion = "The houses of Maldraxxus are once again in balance, and not a threat to us... for now at least. \n\nYou did great!", objectives = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60421] = { id = 60421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Revendreth", description = "Oh, I'm glad you're here, we've got a problem!\n\nOur friends in Revendreth are struggling under the rule of Sire Denathrius. He was always a cruel leader, and now he's thrown in his lot with the Jailer! \n\nIf Denathrius's control of Revendreth isn't broken, he'll come for us next...\n\nLet's do whatever we can to help them out!", progress = "How are things in Revendreth?", completion = "Ha, take that Denathrius. He won't be allowed to rule the Shadowlands if you have anything to say about it!", objectives = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60422] = { id = 60422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Ardenweald", description = "We cannot stand alone. If one section of the Shadowlands falls, we will all be in danger.\n\nThe great soul-trees of Ardenweald are under assault from many foes that seek to harness their power.\n\nWe must aid our allies in the Night Fae, and punish their enemies for these transgressions.\n\nWe are stronger together.", progress = "Have you completed your task?", completion = "You have secured our alliance with the Night Fae, and in doing so, we hold a stronger position across the Shadowlands.", objectives = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60423] = { id = 60423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Ardenweald", description = "Ardenweald was once a place of peace and regrowth, now beset by dark forces from all sides. \n\nMaldraxxus alone is responsible for challenging those that would disrupt the cycle.\n\nTake our banners, steady your weapons, and bring war to Ardenweald.\n\nFor the Shadowlands.", progress = "How do the boughs break?", completion = "The cycle will continue, as we have willed it to be so. \n\nWith every foe you slay, the name of Maldraxxus is spoken with glory and purpose.", objectives = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60424] = { id = 60424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Ardenweald", description = "Ardenweald is one of our closest allies, and to them we ferry some of the most powerful souls.\n\nShould the weald fall, the devastation that would be unleashed could destroy us all.\n\nWe must aid the Winter Queen. It is the will of the Archon.\n\nGo now, and provide support to the Night Fae.", progress = "Have things improved in Ardenweald?", completion = "Our allies in Ardenweald have sent word of your many deeds. You have shown once more that the Kyrian will fight for the Shadowlands and our allies, no matter the cost. \n\nCourage and wisdom to you.", objectives = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60425] = { id = 60425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troubles at Home", description = "Sometimes we must look inward to find true darkness. Here, in Bastion, where once there was harmony, now we face many foes.\n\nToday, we root them out.\n\nHead into the golden fields, with your weapon in hand. Cleanse us of these foul creatures, aid our forces when they have need of you.\n\nIn the name of the Archon.", progress = "Are the fields cleansed?", completion = "The bells chime in the distance, heralding your return. A glorious sound.\n\nYou have performed a great service today, and truly secured your place among us.\n\nHail, victor!", objectives = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60426] = { id = 60426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Bastion", description = "We, the defenders of the Shadowlands, will never let a great foe go unchallenged.\n\nThe Kyrians of Bastion have long served all denizens of the Shadowlands by ferrying souls. We would be lost without their services.\n\nNow, they too are under attack from within. We must defend them in their time of need.\n\nGo now, and bring glory in the name of the Primus.", progress = "Are the golden fields bathed in blood?", completion = "We will always rise to the defense of the Shadowlands, even if we are weakened from within. \n\nYou have shown that no foe is too far to escape the reach of Maldraxxus.", objectives = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60427] = { id = 60427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Bastion", description = "The denizens of Bastion are a key component to the cycle of power here in the Shadowlands. Without them, we cannot replenish our ranks, and the forces of the Jailer will grow ever stronger.\n\nThey have their own troubles in these times, as well. Today, we must look without, and aid our allies.\n\nTravel to the golden fields, and rid them of their foes. \n\nOnly with allies do we stand a chance against Denathrius.", progress = "Have you completed your task?", completion = "The Archon has sent word of your deeds, and agreed to support us in the battles to come. We will fix this broken cycle, with steps such as this leading the way.", objectives = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60428] = { id = 60428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blade of the Primus", description = "That's everything I need. Time to get to work.\n\nI'd stay close, if I were you. Forging a weapon is never a simple task when the Primus's handiwork is involved.\n\nIf he taught me anything, it was to expect the unexpected.", progress = "Stay close, now.", completion = "The Primus was always fond of his trials. It seems you've passed this one. Well done.", objectives = "Help Bonesmith Heirmir forge your runeblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60429] = { id = 60429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troubles at Home", description = "Look! Look around you! All around us, foes await the crushing hand of victory.\n\nThere is an upset in the balance of power, and with it, the defenders of the Shadowlands are weakened.\n\nThe only cure is more combat!\n\nChallenge the houses that sought to disrupt Maldraxxus, bring them to heel under the weight of your boots.", progress = "Have you littered the ground with the bones of your enemies?", completion = "The stories of your power reverberate across the landscape. The bones of the fallen tremble at your name. Let us revel in your victory today!", objectives = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60430] = { id = 60430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Maldraxxus", description = "The forces of Maldraxxus have long defended the Shadowlands from threats outside of our lands.\n\nNow, they face their greatest threats from within. The balance of power between the houses is broken. It has led them to assault us, and others.\n\nTheir problems are many, our solutions are just. \n\nTravel to Maldraxxus and slay those that would do the Shadowlands harm, providing shelter to your allies when you find them.", completion = "With the houses of betrayal brought to their knees, you have brought us one step closer to peace. The Archon thanks you for your service to the Shadowlands.", objectives = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60431] = { id = 60431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Maldraxxus", description = "The forces of Maldraxxus were once intended to defend the Shadowlands against threats from beyond. They are all but broken, now.\n\nThe houses are in disarray, infighting with one another. We have few allies there, and those that have sided with us are bruised and beaten.\n\nGo now, aid them, and slay their foes. Bring balance back to Maldraxxus, and in turn, will they aid us.", completion = "The warriors of Maldraxxus speak your name, a great victory to have achieved this day. The balance of power will be restored one day, and our alliances will pay dividends.", objectives = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60432] = { id = 60432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troubles at Home", description = "There are many tasks that need your attention outside of the walls of Sinfall.\n\nOur closest allies are under assault from all sides, and the forces of Denathrius are unrelenting.\n\nTake your weapon and steel yourself. Today, we defend Revendreth, and in doing so, further bulwark ourselves against our enemies.\n\nWe will take back what is ours.", progress = "Have you reclaimed our homeland?", completion = "We are more secure in our position due to your actions today. Revendreth will not fall to the sway of Denathrius, not as long as we hold firm.", objectives = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60433] = { id = 60433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Revendreth", description = "We fight not only for might and glory, but for the greater good of the Shadowlands. It is our calling to bring war upon those that would disrupt the flow of souls.\n\nThere is one such betrayer - Sire Denathrius.\n\nBring the vengeance of Maldraxxus down upon his foul crown. \n\nSlay his allies, serve his foes, end his reign in carnage.", completion = "Denathrius did not expect us to rally so quickly, to serve our great purpose in the cycle. \n\nHe underestimated our house for the last time, and has paid the price in blood.", objectives = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60434] = { id = 60434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Revendreth", description = "We all serve the greater purpose here, even those in Revendreth that we may not agree with. We take souls to them in need of a harsher form of cleansing, and it is just.\n\nYet Sire Denathrius has gone too far, and now seeks to control all of the Shadowlands.\n\nWe have friends there, amongst the Venthyr. Aid them, and put their enemies to rest.\n\nThe Word of the Archon is with you.", progress = "Have you returned victorious?", completion = "The crimes of Sire Denathrius could not go unpunished, and you have meted out a proper response today. \n\n<Polemarch Adrestes bows his head in your direction.>", objectives = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60435] = { id = 60435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Revendreth", description = "We never truly counted the forces of Denathrius as our allies, and now he has shown his true colors.\n\nOver many years, he has built an army. One capable of destroying any other land, provided we were divided, and not united. He has empowered monstrous creations and broken them to his will.\n\nWhat better way to secure our allies and test our strength, than to eliminate his most fervent champions.\n\nGo now, and hunt.", progress = "Have you thinned Denathrius's forces?", completion = "The generals that serve our enemies in Revendreth will think twice before attempting to control the Shadowlands. \n\nWe have aided unlikely allies, and forged true bonds with Revendreth today, and it is thanks to you.", objectives = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60436] = { id = 60436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Maldraxxus", description = "Maldraxxus is a land of conflict and strife. There is little better place than to test yourself against the might of the Shadowlands.\n\nThere, you will find warriors that are bred on combat, honed by the sword and hammer, tested in arenas and battlegrounds.\n\nCrash into them like the felling of a great branch, let them see the might of Ardenweald is no less terrifying.", progress = "Have you returned victorious?", completion = "In a land of champions and war, you have proven your worth. Few can claim to have taken on the greatest defenders of the Shadowlands and survived, yet here you stand, a monument to the strength of the Night Fae. \n\nMay it never wane.", objectives = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60437] = { id = 60437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Bastion", description = "Bastion has long been one of our closest allies, and a key to the inner workings of the Shadowlands. We cannot abide dysfunctions in the passage of souls.\n\nThey are beset by a host of issues brought on by dissension in their ranks. Every day, doubt gnaws at their forces, bleeding away their hope, and plunging us further into chaos.\n\nDoubt is a powerful foe, and not easily dispatched. Keep your wits about you and crush these dark thoughts.", progress = "Have you aided the denizens of Bastion?", completion = "You have shown courage in the face of great doubt. There are many kinds of strength, and you have shown that you possess one that goes beyond the blade and bow.", objectives = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60438] = { id = 60438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Ardenweald", description = "The Wild Hunt count as our prey the most dangerous creatures in the weald. Here, you may test yourself against challenges the likes of which you may not have faced in your previous life.\n\nIn our current state, my gravest concern is with Tirna Scithe. Once full of life, it is now overtaken by multitudes of foul creatures. They siphon its power, and though we may never regain the glade, we must not allow this to continue.\n\nTake on this trial, and put an end to the invaders of Tirna Scithe.", progress = "How goes the hunt?", completion = "A quiet has overtaken the glade, the leaves no longer rustle in anguish. This is your doing, and we will not forget this kindness.", objectives = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60439] = { id = 60439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Ardenweald", description = "Our close companions in Ardenweald face challenges unlike any that have previously plagued their peaceful glades.\n\nReady your weapons, for now is the time that the golden shields of Bastion shine. Now is the time to take flight into the weald and show courage in the face of darkness.\n\nIt is not always about us, you see. True courage means fighting for others when necessary, even against overwhelming odds and the most vile of evils.\n\nLight shines only in darkness.", progress = "Have you cleansed the weald?", completion = "I have received word of your great deeds in Ardenweald. They are thankful for your service, and you have proven your courage tenfold today.", objectives = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60440] = { id = 60440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Ardenweald", description = "Looking to prove yourself? I hear there are powerful creatures invading Ardenweald. Sounds like a challenge, no?\n\nSo ready your weapon and get out there! What better place to prove your might?\n\nSmash them to pieces, in the name of Maldraxxus!", progress = "Rip and tear!", completion = "It is a shame your job was completed so quickly. So many foes, so little time!\n\nYou are a good addition to our forces, I really enjoy all of this slaying.", objectives = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60441] = { id = 60441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Ardenweald", description = "Ardenweald was once a place of peace and regrowth, but no longer.\n\nFoes assault the weald from all sides, dark creatures that serve no masters.\n\nThey will not be exempted from the hand of justice. We will bring the trials of Revendreth to bear upon them.\n\nThey will see what we do to those that must be broken.\n\nI accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", progress = "Has justice been served?", completion = "Those that have no masters have learned a lesson today.\n\nWe are their masters, in the end.", objectives = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60442] = { id = 60442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Bastion", description = "Sometimes we need look no further than our own golden hills to find a suitable challenge.\n\nDoubt has crept into the minds of some of the most stoic shieldbearers of the Kyrian people. It has poisoned them against us, and in doing so, harmed the ability of the Shadowlands to heal from this blight.\n\nWe must stand against them, now. \n\nIt will not be easy, but things that are worth fighting for rarely are.", progress = "Have you seen the face of doubt and shown it certainty?", completion = "You have uprooted the seeds of doubt and crushed them with certainty. May their doubts now be about only their own dark paths.", objectives = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60443] = { id = 60443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Bastion", description = "We consider the denizens of Bastion to be allies of a sort. Without their service, we would have no souls, and without souls, we could not raise armies, and without armies, we could not smash our fists against one another in the glorious theatre of battle!\n\n<Grandmaster Volo laughs and smashes his weapon around.>\n\nWe must aid them against their foes, or else the arena will sit barren, and we can't have that!\n\nFind their greatest enemies and turn their bones into golden dust.", progress = "Have you clipped their wings?", completion = "You return victorious, atop a mountain of bloody feathers! Ha ha! Glorious!", objectives = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60444] = { id = 60444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Bastion", description = "Our allies in Bastion have long served the cycle of the Shadowlands, delivering souls in need of our services.\n\nYet, within their ranks, doubt has grown and festered. If this continues, we will all pay.\n\nTheir loss of focus shall not be allowed to continue. We will punish their wandering hearts.\n\nI accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", progress = "Has justice been served?", completion = "The sins of the doubtful have been purged.", objectives = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60445] = { id = 60445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Maldraxxus", description = "The purpose of Maldraxxus is to raise the most competent and confident warriors that the Shadowlands has ever seen, to create the perfect army in order to defend us against threats from the outer worlds.\n\nHere, you will find some of your greatest challenges.\n\nSeek out the champions of the strongest houses, stand against them, and let them see your might.", progress = "Do you stand victorious?", completion = "You stand alone atop a pile of bones, as a true master of combat. You have shown yourself a real Necrolord today!", objectives = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60446] = { id = 60446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Maldraxxus", description = "Those of Maldraxxus are the chosen warriors of the Shadowlands, charged with defending us against threats from other worlds.\n\nFor many years, a careful balance has been maintained between the houses. Now, there are those that have broken this balance, and we are all left weakened and defenseless.\n\nThey must pay for these transgressions.\n\nI accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", progress = "Has justice been served?", completion = "Let this be a lesson to them, Revendreth will not stand by and let the balance be disturbed.", objectives = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60447] = { id = 60447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Maldraxxus", description = "In Maldraxxus, the House of the Chosen have taken control of large swaths of land, upsetting the balance of power amongst the houses. To them flock the most seasoned gladiators and warriors.\n\nWhat better place to test yourself?\n\nHead into the land of bones and blood, and stand against their most powerful minions. Prove true what you know to be inside of yourself.", progress = "Have you found the truth in courage?", completion = "The mightiest gladiators have fallen to your hand, and in doing so, you have shown that we, too, will defend the Shadowlands if necessary. Let this be a lesson to them.", objectives = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60448] = { id = 60448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Revendreth", description = "Those that have taken up arms against us in the name of Sire Denathrius and the Jailer have turned their backs on us all.\n\nSome are mere pawns in this game, others command them. Those that lead the charge of this crisis bear the greatest responsibility. \n\nThey are the mightiest of Denathrius's allies, and they must be brought to justice.\n\nI accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", progress = "Has justice been served?", completion = "Justice has been served.", objectives = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60449] = { id = 60449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Revendreth", description = "I've never really trusted the Venthyr of Revendreth. Maybe it's those long coats they wear, or maybe it's those pointy teeth, but something about them creeps me out.\n\nTheir leader, Denathrius, has sided with the Jailer against the rest of us, so I guess I was right.\n\nI want you to find his most powerful allies in Revendreth and smash them to a bloody pulp. Send him a message from Maldraxxus.", progress = "You didn't let them bite you, right?", completion = "I have heard of your bloody exploits in Revendreth, and I am pleased. \n\nDid you bring me back any of their teeth? No? Well, maybe next time.", objectives = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60450] = { id = 60450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenges in Revendreth", description = "Challenging oneself is a necessary part of ascension, for what is courage in the face of normalcy? \n\nIn this current state of unrest, opportunities abound to prove ourselves. Consider it the gilded lining to a tarnished shield.\n\nNone more so than in Revendreth, where Sire Denathrius has consolidated power and influence, and seeks to overthrow the natural order of the Shadowlands.\n\nAnd here is where you must challenge yourself today.", progress = "Have you proven your worth in Revendreth?", completion = "Even so far from our fields, you stood strong against the evils you found, unflinching. This is true courage.", objectives = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60451] = { id = 60451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Enough", description = "Well done, recruit. These were merely the first of many assignments in your future.\n\nMatters here demand my attention. Report to Baroness Draka and see what need she has of you.\n\nI will watch closely as this war unfolds.", completion = "Good work. I see that our defenses have been shored up.", objectives = "Return to Baroness Draka.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60452] = { id = 60452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm the Maw", description = "Oh no, no no no. The Jailer's taken all the souls, and now he's also got a whole lot of anima! Who knows what he's going to do with it!\n\nYou need to go back there! You're the Maw Walker!\n\nSee what you can learn of his power, and slow him down however you can. I believe in you!\n\nBe careful, ok?", completion = "You did great! We learned a lot from your reports, and it sounds like you did some good down there. Good job!", objectives = "Kill 3 rare or special encounter bosses in The Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60453] = { id = 60453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to Glory", description = "It's been some time since I had a chance to craft a weapon that powerful! Good to know that the skills I learned from the Primus haven't dulled.\n\nYou'd best get back to the baroness with that runeblade. I'm sure the margrave will want to know you wield it, as well.\n\nThe Primus was notorious for thinking ten paces ahead of everyone else. I suspect he knew that someone like you would take up that blade.", completion = "You wield a fine weapon. Now you must put it to use.", objectives = "Return to Baroness Draka with your runeblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60454] = { id = 60454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm the Maw", description = "We have been able to do little to stem the flood of souls into the maw, until now. You, Maw Walker, have the power to put a stop to this.\n\nWe know little about the Jailer's lands, save that he is powerful beyond imagining.\n\nI ask something of you today that I would not place upon anyone else. You must travel to his lands, and do what you can to slow the growth of his forces.\n\nWe must buy more time.", completion = "You have shown us many things we could not see ourselves, and now perhaps we can begin to formulate a plan. \n\nYou have done us a great service today.", objectives = "Kill 3 rare or special encounter bosses in The Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60455] = { id = 60455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm the Maw", description = "We cannot allow the Jailer to grow in power. You alone can take the battle to his lands, and you must do so, or we will all fall.\n\nReturn to his lands, Maw Walker. He has already shown his hand, and we know he grows in power with each passing day.\n\nHis forces must be slowed, make what progress you can.", progress = "You seem different, somehow.", completion = "He has seen you, and you are now marked. Wear this as a badge of honor. None other could have done what you did.\n\nHe is not afraid, yet, but he will be.", objectives = "Kill 3 rare or special encounter bosses in The Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60456] = { id = 60456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm the Maw", description = "We know little about the maw, Maw Walker. Only you have the power to traverse those lands and return.\n\nWhat I am about to ask of you I would not dare ask of another.\n\nWe cannot allow the Jailer to grow in power. You must travel to the Maw and take the battle to his lands.\n\nMake what progress you can, we must slow down his forces however possible.", completion = "We have learned much from your travels into the Maw, and we shall plan for the future.\n\nThere was no other way to slow the Jailer's consolidation of power, you have done us a great service, Maw Walker.", objectives = "Kill 3 rare or special encounter bosses in The Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60457] = { id = 60457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Salvage", description = "So many souls that should have been nurtured here have been lost to the Maw, it pains me to think of it.\n\nMaw Walker, we ask you now to do that which we cannot. Traverse the Jailer's domain, walk his barren fields, climb his accursed tower.\n\nBring us that which we lack.", progress = "Have you recovered the Anima Embers?", completion = "You have done us a great service today, Maw Walker. We shall use these to nourish what we can.", objectives = "Gather 150 Anima Embers from Torghast, Tower of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60458] = { id = 60458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Salvage", description = "When we ferried souls to the Arbiter, we never thought this would happen. We watched in despair as they were cast into the Maw, one by one, then by the hundreds and thousands.\n\nSouls that have been devoured, consumed, their anima lost to us. Return to us what you can.", progress = "Have you secured the lost Anima Embers?", completion = "While it is not the same as returning the souls, their power shall not go to waste. You have my thanks.", objectives = "Gather 150 Anima Embers from Torghast, Tower of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60459] = { id = 60459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Salvage", description = "The Arbiter has done us a great disservice. Our armies dwindle in number as souls are cast into the Maw instead of taking their place on the battlefields of Maldraxxus.\n\nThe Undying Army must not be snuffed out. If the Shadowlands are to survive, we must be able to supply our troops.\n\nTravel now into the Maw, Maw Walker, and enter Torghast. Return with Anima Embers to help kindle our supplies.", progress = "Have you brought Anima Embers for our stockpiles?", completion = "The armies of the undying will not fall today, Maw Walker. You emerge victorious once more in the face of great power, impressive.", objectives = "Gather 150 Anima Embers from Torghast, Tower of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60460] = { id = 60460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Salvage", description = "Revendreth is not a place that many souls choose to go, but it is a place that they must go. Here, their sins are laid bare before them, and they are broken and re-formed to function in our society.\n\nThis is a necessary part of the cycle.\n\nYet now, the cycle is broken, and are unable to serve our great purpose.\n\nIn order for us to do our work we require Anima. Travel to Torghast, Maw Walker, gather that which we can not. Without it, we wither and fade.", progress = "Have you brought the Anima Embers to us?", completion = "These Anima Embers will serve us well, Maw Walker.", objectives = "Gather 150 Anima Embers from Torghast, Tower of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60461] = { id = 60461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the Margrave", description = "Word of the runeblade has reached Margrave Krexus. He wishes to see it for himself.\n\nWith such a weapon by your side, you pose a threat that the other houses cannot ignore. Perhaps we can use that to our advantage.\n\nBut enough talk. Follow me.", completion = "Show me this runeblade of yours, mortal.", objectives = "Present your runeblade to Margrave Krexus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60462] = { id = 60462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Appeal", description = "Maw Walker!\n\nThe Anima Reservoir is nearly depleted. Without more anima, the groves shall soon wither and die.\n\nSearch the realms for additional nourishment and deliver it to the sanctum.\n\nArdenweald cannot continue without your aid!", objectives = "Deposit 600 anima in the Anima Reservoir at the Heart of the Forest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60463] = { id = 60463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Appeal", description = "Maw Walker!\n\nOur anima stores have run low, and soon we will have nothing to sate our thirst...\n\nSeek out additional sources of anima amongst the realms of the Shadowlands and deliver it to the sanctum.\n\nThese are dire circumstances. Our fate is in your hands.", objectives = "Deposit 600 anima in the Anima Reservoir at Sinfall in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60464] = { id = 60464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Appeal", description = "Maw Walker!\n\nOur anima reserves are nearly depleted. Without an additional supply of anima, our mission of conquest will be lost!\n\nScour the realms for all the anima you can gather and deliver it here to the sanctum.\n\nVictory depends on your success!", objectives = "Deposit 600 anima in the Anima Reservoir at Seat of the Primus in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60465] = { id = 60465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Appeal", description = "Maw Walker!\n\nOur supply of anima is dwindling and the reservoir is nearly depleted. We must replenish our reserves before it is too late!\n\nSearch the realms for all the anima you can gather and deliver it to the sanctum.\n\nTime is short. Move swiftly, {class}.", objectives = "Deposit 600 anima in the Anima Reservoir at Elysian Hold in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60466] = { id = 60466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Old Ways", description = "You there! Might I ask your help?\n\nI must confess, with the lack of new souls arriving, our supplies have dwindled. We lack the means to clothe arrivals in proper kyrian attire.\n\nBefore the forging of the centurions, aspirants trained against the native wildlife. Perhaps there is another way these beasts can prove useful.\n\nIf you collect materials from the cloudstriders and larions nearby, we can use them to ensure our new arrivals look the part.\n\nOh, and some thread from Mirene, if you would!", progress = "How goes the hunt?", completion = "These are perfect! Go in service, always.", objectives = "Collect an Elysian Thread, 4 Cloudstrider Pelts, and 12 Larion Plumes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60467] = { id = 60467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rousing Aroma", description = "<Sabina is unresponsive. Her exposed flesh cracked and blistered. Perhaps something with a pungent aroma will rouse her.>", progress = "Sabina remains unresponsive.", completion = "<Sabina begins to stir. >\n\nAre... are they back? Help... help me.", objectives = "Collect 4 Pungent Swarmer Toxin from Ravenous Swarms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60468] = { id = 60468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rubble Rummaging", description = "I do not know how long it's been since my captors left me here, but the Light has... taken its toll. \n\nYou must help me escape. The key to my shackles should be hidden nearby. Perhaps among the rubble? That's likely where I'd hide something small.", progress = "Have you found the key?", completion = "This looks like it could fit.", objectives = "Find a Shackle Key among the rubble within Ashen Traverse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60469] = { id = 60469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safe in the Shadows", description = "I cannot recollect what happened. Perhaps the Light has burdened my memory? Who knows how long I've been out here...\n\nThe last thing I remember before things went dark... my companions and I had finally found refuge in the shadows. I worry for their well-being. \n\nSo long as my assailants remain at large, my companions could be in danger. Will you find them and ensure they're still safe in the shadows?", completion = "They've perished? Are you sure? Who could have done something so cruel...", objectives = "Find out what happened to Sabina's companions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60470] = { id = 60470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting Sabina Free", description = "Release me. Please, you must do so. I cannot linger in the Light any longer. \n\nThis unease, it's so... familiar, but it will pass. I will feel myself once again, once I have returned to the shade.\n\nI'll stay as still as silence while you work the lock.", objectives = "Release Sabina from her shackles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60474] = { id = 60474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spawn Tracking Unit-Specified World Effect in a WMO Bug", description = "There seems to be a bug when you setup a world effect containing a gold dot on the minimap through Spawn Tracking that is set to Unit, rather than Objective. It seems to only happen with spawns inside WMOs. Might also be happening with setting it to Object as well.\n\nIf the Spawn Tracking on the World Effect is set to Objective, everything's fine. However, if it is set to Unit, the golden dot will not show up on the minimap.", objectives = "Attempt to figure out why the WMO spawned objective's minimap golden dot will not appear when its spawn tracking is set to Unit instead of Objective.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60475] = { id = 60475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We'll Workshop It" }
quests[60476] = { id = 60476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spriggan Size Me!" }
quests[60480] = { id = 60480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endmire", description = "Oi! You.\n\nNot sure what landed you in the Endmire but I need your help.\n\nSee these torches? It's my gig to keep 'em lit. But it ain't like they runnin' on flint n' tinder.\n\nMy stash of infused rubies got hauled off by some devourers when my back was turned. Can ya find 'em before we both get ate by one of these horrors?", progress = "Just going to be clear on this: I... HATE... THIS... GIG.", completion = "Much obliged. These torches keep the effects of the Endmire at bay. Even scares away the devourers for the moment. Only lasts so long though. \n\nI miss the good ol' days of only having to worry about manifestations down here.", objectives = "Find 5 Infused Rubies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60482] = { id = 60482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See With My Eyes", description = "After the destruction of our house, the spiders in this area become increasingly hostile. They expand their domain, and prey upon the few survivors that live here. \n\nThere are weapons we could use to help protect ourselves, but they lie hidden within the Sightless Hold, webbed over by the weavers that inhabit it now.\n\nJourney to the hold, use my sightless vision to see the weapons and recover what you can.", progress = "Have you recovered the weapons.", completion = "You can kill more of them if you want.", objectives = "Collect 10 hidden weapons", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60487] = { id = 60487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Used to Be Quiet Here", description = "Well... You don't look like the rest of 'em, do you?\n\n<Chiselgrump shrugs.>\n\nDoesn't bother me. Keep my head down and do my job, making sure these sinstones stay in good shape.\n\nKeep breaking my tools, though.\n\nBring me some more chisels and I'll teach you an old dredger construction trick.", progress = "Got those chisels yet?", completion = "Yeah, these'll last me awhile.\n\nAlright, I'll show you the trick to making a barricade quickly...", objectives = "Collect 8 Dredger Chisels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60489] = { id = 60489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Ascension", description = "With the anima you collected, we can once again start up the Path of Ascension.\n\nThe eternal training ground of the kyrian, the Path is an ancient tradition and favored amongst many of the kyrian, aspirant and ascended alike.\n\nThe Hands of Courage, Apolon and Artemede, have stepped up to lead this tradition. Once you herald the Path's rebirth, speak to them to learn more.", completion = "By your hand, the coliseum is powered by anima once more. Glory awaits you and your allies in the Path of Ascension!", objectives = "Activate the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60491] = { id = 60491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Among the Kyrian", description = "You will be well at home among the kyrian, <brother/sister>. We welcome your aid.\n\nThe Archon was so confident in this outcome that she has arranged a grand reception for you in honor of your efforts against the Maldraxxus incursion into our realm.\n\nFor now, all you must do is journey to the Seat of Eternal Hymns. I shall meet you there.", completion = "Much has culminated in this moment.", objectives = "Meet Polemarch Adrestes at the Seat of Eternal Hymns in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60492] = { id = 60492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Reception", description = "Though the path you follow is not that of a traditional ascended, it is a kyrian path all the same.\n\nTo follow it is to bask in the footsteps of the innumerable lives before us, forever in service to a good far greater than we can achieve alone.\n\nTo join us amidst such strife is an accomplishment worthy of recognition. Our Archon has called all among us to join her in welcoming you to our ranks.", progress = "This is the final step of joining our ranks. Should you have second thoughts, have them now.", completion = "May this be but the beginning.", objectives = "Join the Kyrian Covenant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60493] = { id = 60493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Humble Gatherer", description = "Before your soulbinds step foot in the coliseum, you must challenge your first opponent.\n\nThere is a tradition to this, as with all things. You will need to gather specific items, then bring them back here to fashion armaments to help execute your challenge.\n\nIn the case of your first challenge, you will find the materials throughout Bastion. Return to me once you have collected everything, then we will continue.", progress = "Though the Path of Ascension leads to glory, participants must remember to stay humble and grounded in the tradition.", completion = "You have taken the first steps. A commendable feat!", objectives = "Collect 2 Depleted Goliath Cores from Forsworn goliaths, 6 Tampered Anima Chargers from Forsworn centurions, and 5 Soul Mirror Shards from Forsworn kyrian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60494] = { id = 60494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Friend, Dactylis", description = "With the materials you gathered, you are now ready to craft your lure.\n\nReport to Dactylis. She will be able to help you craft not only this, but many more items of all kinds later.\n\nOnce you craft your lure, return to me and I will give you your next instruction.", progress = "Inspired by the Collectors, we must take the time to craft by hand. Through crafting we practice patience, diligence, and humility.", completion = "Every time you craft, a piece of yourself is imbued in whatever you create.", objectives = "Speak to Dactylis to craft 2 Overcharged Goliath Cores and 1 Soul Mirror.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60495] = { id = 60495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Suitable Opponent", description = "The opponents you train against in the coliseum are not physical beings, but rather manifestations of such.\n\nYour first opponent is one you and your soulbinds have met numerous times before -- the Ascended Kalisthene.\n\nAsking another kyrian to be your opponent in the Path is a great honor, as it tells them that you have much to learn from them.\n\nGo to Aspirant's Awakening and use the cores to summon Kalisthene by calling back to your first introduction. It is as ceremony states.", completion = "Kalisthene will train your friends well.", objectives = "Use the Overcharged Goliath Cores on the Depleted Goliaths in Aspirant's Awakening, then use the Soul Mirror to capture a memory of Kalisthene.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60496] = { id = 60496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Coliseum", description = "The time of your challenge has come!\n\nAs you are not a being of Bastion, you shall act as a tactician for your soulbinds. You have developed mighty bonds between each other... let us see how they handle the coliseum.\n\nLet me know when you are ready to begin. Show us the merit of your bonds!", progress = "This is just the first of many challenges ahead of you, {name}. Remember to stay humble.", completion = "A lesson in humility. But not one without purpose.\n\nThis blueprint will serve you well.", objectives = "Speak to Artemede to challenge the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60497] = { id = 60497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herald's Footpads", description = "Sometimes, sheer force of will is not enough. A piece of equipment can save your life.\n\nThis blueprint you found can teach you to craft your first piece of equipment.\n\nBring it over to Dactylis. She will be able to aid you in this as well.", progress = "Welcome back. How may I aid you?", completion = "Ah, a new blueprint! Let us get started, yes?", objectives = "Bring the Blueprint: Herald's Footpads to Dactylis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60498] = { id = 60498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overcoming the Trial", description = "These new footpads can give Pelagos the edge he may need to defeat Kalisthene.\n\nReturn to the Path, {name}. Equip Pelagos with these footpads and overcome your opponent.\n\nIt may take a few tries, but all trials do.\n\nGo in service, and in glory!", completion = "More trials lie ahead, {name}. Your future experience with the Path of Ascension is yours to guide!", objectives = "Defeat Kalisthene in the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60500] = { id = 60500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Atonement: Medallion of Pride", description = "Our attempts at a parley were met with skepticism, at best. Acquiring the medallions may take more work than originally intended. However, not all hope is lost. \n\nI do believe that we can win over many of the Harvesters, and for those we cannot, a more direct approach will need to be taken. \n\nLord Chamberlain falls into this latter category. His medallion must be taken by force.", progress = "Have you recovered the medallion?", completion = "With this, we are one step closer to realizing the revitalization of Revendreth.", objectives = "Recover the Medallion of Pride from Lord Chamberlain within the Halls of Atonement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60501] = { id = 60501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redemption for the Redeemer", description = "<Energies of death and innervation struggle to free themselves from the blade and consume you to your very core.>\n\n<The bonds of warding placed on this blade by Prince Renathal will not hold for long. It should be taken to Sinfall where more permanent arrangements have been made for this prisoner.>", completion = "Denathrius once served a noble cause. His charismatic leadership and understanding of the dark desires were instrumental in the redemption of more souls than your world has known.\n\nPerhaps in time, he could be this again. If the right lessons were to remind him of his true purpose.", objectives = "Deliver Remornia to General Draven on the edge of Sinfall.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60502] = { id = 60502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanguine Depths: An Ally Within", description = "There are whispers of a prisoner within these depths that may be of use to our cause. \n\nWhether this information can be relied upon is unknown. It is just as likely to be a trap, but still, we must investigate. \nWe cannot afford to ignore an opportunity such as this. \n\nVenture into the Sanguine Depths and recover this valuable prisoner.", completion = "This naaru shall prove an invaluable ally.", objectives = "Recover the valuable prisoner from within the Sanguine Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60504] = { id = 60504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strengthen the Bond", description = "To bond souls is but the first step. You must now explore its potential.\n\nJust as Pelagos will gain strength from you, so too shall you grow from him. As your bond grows over time you will touch deeper into one another's souls, and so your strength shall increase. \n\nAll you must do is place your hand upon the Forge of Bonds to augment your bond. There is no price to pay--the only limitation is your connection to our sacred covenant.", progress = "This device is merely a pathway to the strength that lies within you both.", completion = "May you prove worthy allies to one another in the trials to come.", objectives = "Activate a Soulbind Power using the Forge of Bonds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60505] = { id = 60505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spider's Lair", description = "When our house fell in ruins, Manipulator Zalisar seized the opportunity to reform the house under his leadership. He found few followers and soon vanished into the ruins nearby. \n\nHe has begun to manipulate the spiders and train them to be his soldiers. Spiders under his control have begun to prey upon our forces. We need to deal with this threat before it grows any worse.\n\nI need you eliminate Manipulator Zalisar and his spider forces.", completion = "Your help is always welcome, Maw Walker.", objectives = "Slay 8 Razorweb Weavers and Manipulator Zalisar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60506] = { id = 60506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Accuser", description = "It is time to hunt our final prey, the Accuser.\n\nAnima drought or not, her sycophantic adherence to sacred \"rituals\" flies in the face of the Master's will. I can't wait to see the fear in her eyes.", completion = "We meet again. Under dire circumstances I fear.", objectives = "Hunt the Accuser.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60508] = { id = 60508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Trail", description = "In my visions, I witnessed Tyrande cutting through an endless storm of malevolent, nightmarish beings.\n\nUp ahead... is that...? Yes. I believe it is the very place I saw.\n\nCome. It may hold a clue as to where my mother has gone.", completion = "Some vile force in this place intends to stop us from finding Tyrande.\n\nIf experience serves, that means we must be on the right track.", objectives = "Look for signs of Tyrande Whisperwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60509] = { id = 60509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not My Job", description = "Right. So, 'em devourers are going to start creepin' out of the Endmire soon. \n\nAnd with the anima drought puttin' the squeeze to the fangs... well... we ain't gettin' help from them until it's too late.\n\nUs dredgers could use someone in your line of work. Professional destroyer as it were. \n\nIf you can spare the time, meet me out at the Dredgewood. We'll scoop up a couple of lads and see if we can't make a stand.", completion = "I see you decided to get your hands dirty and join us gents in the labor pool.", objectives = "Meet Rendle in the Dredgewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60510] = { id = 60510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Descended", description = "Though we have stopped the creation of more juggernauts, one of their most vile creations yet draws breath. It was born of one of the most pained souls they took from my temple in Bastion.\n\nAs I flew above their ranks I could hear their surgeons chanting its name above the din of combat--Woeblade. It is an affront to all the kyrian stand for, an atrocity beyond any other.\n\nMark it with the flames of courage when you engage, and we will help you destroy it.", completion = "May our victory bring them peace.", objectives = "Slay Woeblade the Atrocity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60514] = { id = 60514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Trophies", description = "To be a hopebreaker is to conquer all prey, not just souls.\n\nThe Banewood is home to many dangerous creatures: deathwalkers, fearspinners, and the horrifying doomfangs. If you wish to really master the art of the hunt, you should be able to defeat these foes.\n\nBring me trophies as proof of your conquests. Then, you may just earn my respect.", progress = "Have you conquered the creatures of the Banewood?", completion = "<Constantin examines what you have brought him>\n\nWell done. You may make a fine hopebreaker yet.", objectives = "Collect 3 Doomfang Skulls, 3 Pristine Deathwalker Paws, and 3 Prized Fearspinner Fangs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60517] = { id = 60517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Toll of the Road", description = "This vessel appears to be brimming with anima. It is certainly tolls collected from denizens traveling by this crossroads. I am sure with all that is going on, Mistress Mihaela in Darkhaven would appreciate these tolls brought to her to cover the Village Ward's obligations.", completion = "What is this? The road tolls! Varaboss, that conniving fiend, never did master his greed. Your kind prefers this precious metal as recompense I believe.", objectives = "Return the tolls to Darkhaven.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60519] = { id = 60519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audience with the Winter Queen", description = "Zephyrs herald the Queen's arrival. Hushed silence descends upon the grove.\n\nWait, watch, and speak when the time has come.", progress = "The Queen shoulders so much because of this drought. But she is powerful, and I know we will make it through.", completion = "Gone so soon... the forest must be in even more dire straits than I realized.\n\n<Moonberry looks crestfallen for a moment before resolutely setting her hands on her hips.>\n\nWell, then we'll just have to help ease the Queen's burden. Then she'll have the time to grant you an audience!", objectives = "Speak to Moonberry and await the Winter Queen's arrival.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60520] = { id = 60520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightmares Manifest", description = "Oh, this isn't good. As soon as you left, the spirit's nightmares spilled out all over Tirna Vaal. \n\nI've done everything to try to soothe her. I've tried singing to her, I've tried telling her stories, but nothing I do seems to calm her.\n\nPlease, would you confront and dispel her nightmares? That might be the only thing that will work.", progress = "Her dreams are usually beautiful.", completion = "There, that seems to have calmed her. I can feel her dreams begin to ease.\n\nYou really do have a knack for this!\n\nBut I'm worried that we're only buying time, and we need to do something more drastic.", objectives = "Confront the wildseed's nightmares in Tirna Vaal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60521] = { id = 60521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Hunt", description = "You've done so much, but the Queen's focus is still divided across the forest.\n\nIf you want to deliver your message, then we need to help lessen her burden.\n\nLet's start with the Wild Hunt. They are the protectors of Ardenweald, and dealing with the threat of the masked fae has stretched them thin.\n\nSeek out Hunt-Captain Korayn at Glitterfall Basin. Last I heard, her hunting party could use reinforcements.\n\nAnd don't let her ferocity put you off. She's quite nice as long as you're not her prey!", completion = "Lady Moonberry said she would be sending a strong hand to help secure this grove.\n\nNow, how are you in a fight?", objectives = "Seek out Hunt-Captain Korayn in Glitterfall Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60522] = { id = 60522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Tirna Vaal", description = "We of the Wild Hunt are always prepared to return to the cycle in defense of Ardenweald.\n\nI must move on, and so should you. I advise you to return to Droman Tashmur in Tirna Vaal. Others will need your help.\n\nHere, take this. It is a gift and a thank you.\n\nHelping each other is the only way to survive this drought.", completion = "Oh, you have a spirit cradle! That will be quite useful, indeed.\n\nAssuming we can calm this chaos, of course. The wildseed you bonded with is having intense nightmares... and they're manifesting all over the grove!", objectives = "Return to Tirna Vaal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60530] = { id = 60530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sea of Souls", description = "Some force here seeks to keep us from finding Tyrande.\n\nThe trail of bodies seems to go into this... stream of souls. \n\nI suggest we split up. I will follow along the bank of the river. You enter its current and follow the trail.\n\nShould you need me, I will be close at hand.\n\nWe will find Tyrande, no matter where this course leads.", completion = "Tyrande must see reason. She cannot save the kaldorei if she remains lost within this darkness.", objectives = "Follow the trail of corpses to Tyrande Whisperwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60531] = { id = 60531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chosen Champions" }
quests[60532] = { id = 60532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Dominant" }
quests[60533] = { id = 60533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrors in Tirna Scithe" }
quests[60534] = { id = 60534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disloyal Denizens" }
quests[60542] = { id = 60542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nathanos Blightcaller" }
quests[60545] = { id = 60545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowlands: A Chilling Summons", description = "The time has come, {class}.\n\nHighlord Bolvar Fordragon requests your presence atop Icecrown Citadel. Meet me in Stormwind, and I will take you to him.\n\nI would not keep him waiting.", completion = "It is good that you have arrived.\n\nWe need heroes like you in this dire hour.", objectives = "Meet Darion Mograine outside Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60557] = { id = 60557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Time? You Have to Fight!", description = "When it comes to warfare, strength of will is as critical as strength of arms. A demoralized soldier is a defeated soldier!\n\nWe have the numbers to overwhelm the constructs with a full scale assault, but only if our forces are fully committed to the charge. Some may fall, but their sacrifice will secure our victory!\n\nTake this battle horn and rally our troops. Remind them of their duty to the Chosen!", progress = "Have you rallied the troops?", completion = "Our forces stand ready to fight once more!", objectives = "Rally 8 demoralized soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60563] = { id = 60563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tending to Wildseeds", description = "We infuse wildseeds with anima from the animacones we collect in the surrounding area.\n\nBut the caretakers are missing, and we have wildseeds in need of an anima infusion.\n\nThis is an absolute mess that must be corrected before the Winter Queen arrives!\n\nI've already gathered a basket of animacones. Can you use them to infuse a few of the wildseeds?\n\nI'll show you how it's done, but then I have to look for the missing caretakers.", completion = "Fine work. We mustn't stop tending to the wildseeds that the Winter Queen has chosen to be saved.\n\nNow, perhaps you can lend me a hand with another matter.", objectives = "Collect basket of animacones, then use them on 4 wildseeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60564] = { id = 60564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Gorm Enter, No One Leaves" }
quests[60565] = { id = 60565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Steward for Every Occasion" }
quests[60566] = { id = 60566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Light", completion = "<Breakfist is badly injured.>\n\nToo many... couldn't make it...", objectives = "Take the elevator up to Sinfall and investigate the area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60567] = { id = 60567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shooing Wildlife", description = "Things are chaotic here in the Tranquil Pools. I'd be devastated if the Winter Queen saw this.\n\nThis is meant to be a peaceful place where we give anima to wildseeds.\n\nBut with the current drought, starving beasts have encroached on the pools and are trying to feed on the anima themselves.\n\nSadly, we need to put them down... or else they may endanger the spirits within the wildseeds.", progress = "I hate having to do this, but if it's a choice between sparing the beasts and saving the wildseeds, I have to choose the wildseeds.", completion = "Normally, I wouldn't require help from whatever race you are.\n\nAh... my apologies. That was rude.\n\nPlease understand that Ardenweald is home to souls from across all of the mortal realm. It's hard for me to keep track of every race that arrives here.", objectives = "Slay 8 Anima-Starved wildlife.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60568] = { id = 60568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TEMP MAW RUN", description = "<Placeholder Quest. Thank you for your patience as our dev team works to make the Maw experience the coolest thing we can. In the meantime, please enjoy a sample of a snarky sword and her fourth wall breaking objectives.>\n\nLook, normally I would give you a quest to storm the very Maw itself looking for Prince Renathal before he gets transferred in to the dreaded Torghast, Tower of the Damned.\n\nHowever, since that is NOT something we can do. Let's just assume we did and go talk to that projection of him", sourceObjective = "Speak with Projection of Prince Renathal.", sourceObjectiveStatus = "unverified-source-field" }
quests[60572] = { id = 60572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Sake of Spirit", description = "With all of the anima you recovered from Tirna Noch, it is only a matter of time before my grove becomes the target of every anima-seeking enemy of Ardenweald.\n\nI hope Dreamweaver knows what he is doing with this ritual.\n\nProceed quickly. Speak with Dreamweaver, and see what needs to be done to aid the spirit within the wildseed.", completion = "You're ready to begin preparing for the ritual? Wonderful.\n\nI am also ready!", objectives = "Speak with Dreamweaver to prepare the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60573] = { id = 60573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meatball's Revenge" }
quests[60574] = { id = 60574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaking 'Shrooms" }
quests[60575] = { id = 60575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belly Full of Fae", description = "The local flora have gone somewhat wild during this anima drought.\n\nIt seems they swallowed most of the young fae who were tending to the wildseeds here.\n\nAt least now we know where they've been.\n\nOh, don't worry. This isn't the first time this has happened. We can last quite a while inside those plants.\n\nTake my dagger. Use it to cut through the shrubbery and free the other wildseed tenders.", progress = "How goes the gardening?", completion = "Great work. This should help get the Tranquil Pools back to normal.\n\nI admit, I had thought the worst when I couldn't find any of the tenders. I'm glad they were only eaten by the local vegetation.", objectives = "Free 16 Wildseed Tenders from inside Devouring Hydra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60577] = { id = 60577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry for Animacones", description = "I have to apologize for the state of the Tranquil Pools. Normally, it's quite peaceful here.\n\nThe wildseed tenders tell me that the plants you see walking around have eaten all the animacones intended for use in Tirna Vaal.\n\nCould you rip the animacones out of those plants?\n\nWe have wildseeds that are in need of that anima.", progress = "Have you found the animacones? They're still useful, even if they're a little slimy. \n\nTrust me, the spirits don't mind as long as they get their anima.", completion = "The animacones! In this time of drought, we have to scrounge for every bit of anima we can get. Thank you.", objectives = "Recover 25 Animacones from Gobbling Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60578] = { id = 60578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Dreamer: The Betrayal", description = "I sense that in the spirit's vision, she struggles with the memory of a betrayal that is truly profound. \n\nSomeone as close to her as a brother, turned to an enemy.\n\nGo to the second Dreamshrine in the Basin, and help vanquish the pain of this nightmare.", progress = "Have you seen what dreams have come?", completion = "To have an old friend turn against you, in the most terrible way. How very painful. \n\nBut we are so close now, to soothing the spirit within the wildseed.", objectives = "Grapple with the Dreamer's vision of a great betrayal.\n\nIf you leave the Vision, interact with a Dreamer's vision portal in Dreamshrine Basin to enter again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60585] = { id = 60585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spriggan Riot" }
quests[60594] = { id = 60594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Special Spirit", description = "You've been a huge help to Tirna Vaal. I need to bring this anima to one of our newest wildseeds.\n\nI'd love for you to come with me. It's only fair, since you're the one who recovered the animacones.\n\nI'm quite excited for you! Let's go.", progress = "The howling wind becomes a gentle breeze. All is well once again.", completion = "Starlight shines within Dreamweaver, radiant and serene.\n\nAnd... two rivers meet in a lush delta. A wildseed and a mortal, both new to the forest. Bonded by spirit and by fate.\n\nLong has it been since the boughs beheld such an event. The weald will be watching.", objectives = "Go with Dreamweaver to feed anima to the wildseed in Tirna Vaal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60597] = { id = 60597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at the Gormling Corral" }
quests[60600] = { id = 60600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing for the Winter Queen", description = "Tirna Vaal is ready for the Winter Queen's arrival! And it's all thanks to you.\n\nYou have more than upheld your end of our bargain... and yet I was not able to do the same.\n\nThat is absolutely unacceptable for a faerie like me! What would the others think if they knew I had failed to honor our agreement?\n\nPlease, allow me to make it up to you. I may not have been able to deliver your message to the Queen, but I have a special surprise that I hope you'll accept instead!", progress = "Joy follows Lady Moonberry, a scent that lingers as a flower blooms.", completion = "Shadows loom over Heartwood Grove. Things unseen crawl within the darkness.", objectives = "Receive Ardenweald's essence from Lady Moonberry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60601] = { id = 60601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkwing Drills" }
quests[60602] = { id = 60602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret Service" }
quests[60605] = { id = 60605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glimmerfin Scale", description = "<A brightly-colored scale fell to the ground as the murloc ran off. It was unlike any other murloc you've seen in Northrend.\n\nPerhaps King Mrgl-Mrgl would know more about this new species?>", completion = "What do you have there? Oh! Isn't this colorful.\n\nYou say there's a new band of murlocs down south? That doesn't surprise me, strange things have been happening in the waters far from here, from what I've heard.\n\nWell, if they're friendly, it's up to us to welcome them! Here's a few potions, you're probably going to need them.", objectives = "Show the scale to King Mrgl-Mrgl in Borean Tundra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60606] = { id = 60606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glimmerfin Welcome", description = "First thing's first, they're probably hungry. Life up here in the cold isn't quite as easy as it is elsewhere, and even the most acclimated murlocs sometimes have trouble finding food.\n\nWe're going to need to feed them, but also help them find food for themselves.\n\nThey're already watching you, so search the area around where you found the murlocs for food sources and show them what to hunt. Then bring the meat to their leader--just look for the biggest one.", progress = "Mrgg?", completion = "Mrg?\n\n<Glimmergut looks at you, then cautiously takes the crab chunks and hands them to a nearby forager. The forager and Glimmergut appear to have a short conversation about your crab hunt.\n\nGlimmergut turns back to you and points down at the sand.>", objectives = "Collect 10 Meaty Crab Chunks and deliver them to Glimmergut in Venture Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60609] = { id = 60609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Devours the Devourers?" }
quests[60614] = { id = 60614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Big Horkin' Task", description = "<Glimmergut begins to draw in the sand.\n\nThe murloc traces the outline of what appears to be a large seal. He points at the picture, then upwards, indicating that the creature must be somewhere on the surface of the water.\n\nThe murloc then digs a small, shallow hole in the sand, and points at it several times.>\n\nMrg! Mrg! Grml.\n\n<He cocks his head expectantly.>", progress = "Grmgr?", completion = "Grml! Mrgl-rgml. M'gurgle.\n\n<Glimmergut looks at the foragers next to him. They nod, and he nods back.>", objectives = "Collect one Pile of Blubberfat and deliver it to Glimmergut in Venture Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60615] = { id = 60615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seer of the Waves", description = "<Glimmergut points across the ship. He wants you to take the blubber to someone.>\n\nMrg m'grrl.", completion = "<The oracle takes the blubberfat from you, as if expecting your arrival, and arranges it in a small pile.>", objectives = "Deliver the Blubberfat to the Glimmerfin Oracle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60616] = { id = 60616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pearl in the Deeps", description = "<The oracle draws a circle in the sand, then points down into the deeps. There is something round down there that she is after, perhaps a pearl or stone?\n\nThe oracle motions for you to wait a moment before you leave. She waves her hands around frantically, then places them under her mouth, mimicking two large fangs.\n\nYou take this as a warning that there may be something waiting for you in the icy darkness.>", progress = "<The oracle looks at you.>", completion = "<The oracle takes the pearl from you and rubs it gently before peering deeply into its shimmering depths.>", objectives = "Collect the Giant Pearl and deliver it to the Glimmerfin Oracle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60617] = { id = 60617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trainer's Test", description = "<The oracle finishes peering into the pearl and turns to face you. She appears to be deep in thought, staring directly at you and blinking a few times.\n\nFinally, she nods. \n\nThe oracle points at you, then points upwards. She places a hand a small distance above the ground, indicating something pet-sized.\n\nYour surmise that there may be test of your connection with your battle pets ahead.>", progress = "<The oracle looks very excited.>", completion = "<The oracle looks excited at your return. She points rapidly down at the blubber pile next to her, where an egg has been softly nestled.>", objectives = "Defeat Trainer Grrglin in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60619] = { id = 60619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrap it Up", description = "<The seems quite excited about the presence of the new egg. You get the sense that this is an important occasion for these murlocs--there may be few eggs left.\n\nThe oracle waves a small piece of seaweed in front of you, showing you the young buds of the immature plant.\n\nShe warps the seaweed around a small part of the egg, then points at you, then back at the wrapped seaweed.\n\nIt appears that the egg needs to be wrapped in more immature seaweed stalks.>", progress = "<The oracle blinks at you.>", completion = "<The oracle wraps the egg gently in the seaweed.>", objectives = "Collect a Warm Seaweed Stalk, a Young Seaweed Stalk, and a Bulbous Seaweed Stalk and deliver them to the Glimmerfin Oracle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60620] = { id = 60620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardian of the Smallest", description = "<The oracle pats you on the shoulder, and seems quite pleased with all that you've done.\n\nShe holds up one finger, then spreads her hands wide and emits a terrible roar-like murgle.\n\nShe points outside, then at you, then your weapon, then nods seriously.\n\nThere must be one more trial to await you. It would appear to be a test of strength.>", progress = "<The oracle claps excitedly.>", completion = "<The oracle pats you excitedly on the shoulder, and raises her arm in triumph.\n\nShe starts, then points quickly at the egg and rushes over.\n\nThe egg begins to hatch...>", objectives = "Slay Great Mua'kin and return to the Glimmerfin Oracle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60621] = { id = 60621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies at the Gates", description = "Lorkron is here. \n\nI tracked him all the way from the Glittering Falls. Then I saw the Drust try to flank our forces.\n\nI'd say they were rather surprised that we turned the tables against them.\n\n<Korayn's smile is fierce. She lifts her weapon and her voice to address all present.>\n\nHuntsmen and huntresses, with me! We ride to defend the grove! Take no prisoners and leave none standing!", completion = "This attack... It is like they are being driven!", objectives = "Reach Droman Aliothe in Hibernal Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60622] = { id = 60622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of the Scryer", description = "Evading the Mawsworn's scryers requires powerful magical countermeasures.\n\nThe prime reagent? A luminescent eye, pried from the skull of a scryer recently shaken from its trance.\n\nThe scrying ritual begins as we speak. You will, of course, be compensated only for an intact eye.\n\nRestraint is advised in its procurement.", progress = "Well? Do you have it, undamaged?", completion = "Do you think he saw that one coming?\n\nThat was an attempt at mortal humor. You may laugh at your leisure.", objectives = "Obtain the Eye of the Scryer from Leerok the Scryer in The Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60623] = { id = 60623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AHHH! Real Monsters!" }
quests[60624] = { id = 60624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ride to Heartwood Grove", description = "A storm of strife and fear rains down upon Heartwood Grove. Sylvar flee from the flood.\n\nBrave the torrent astride a stag. Becalm the deluge and be the salvation of those who would drown.\n\nMake haste. Time wanes.", completion = "We can't leave Heartwood Grove like this.", objectives = "Ride a stag to Heartwood Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60628] = { id = 60628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Hunters", description = "Strange creatures have been seen lurking just outside the grove. Terrible, ugly things.\n\nWhatever they might be, they are not native to Ardenweald. \n\nIt does not matter how they breached our borders, though. Every one of them must be eliminated.\n\nI sent my best huntsmen and huntresses to slay them, but not one has returned. See if you can determine what has delayed them.", completion = "Only Ara'lon and Lumera survived? The rest have fallen?\n\n<Korayn trembles with unbridled fury.> \n\nI will see to it that their bodies are retrieved. And this cannot go unpunished. We will avenge them all!", objectives = "Find Jynkla, Serinkai, Rondar, and Ara'lon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60629] = { id = 60629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extreme Recycling", description = "The Wild Hunt serves the Winter Queen under the leadership of Lord Herne. We are elite fighters, hunters, and trackers.\n\nBut we cannot fight without weapons and supplies. The droman here informs me that there are severe obstacles to their delivery.\n\nI do not have time to wait. We need equipment, and we need it now.\n\nSee what you can scavenge from the field. A broken weapon can always be mended and put to use again.", progress = "Did you find anything of use out there?", completion = "You found far more weapons than I expected.\n\nVery strange. How could they acquire so many of OUR blades?\n\n<Korayn appears troubled.>\n\nThey will be used against our enemies again, I swear it.", objectives = "Slay the Blighted and take their weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60630] = { id = 60630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem Eclipse", description = "I can smell our foes' dark magic, twisting the air and muddling my mind. They are up to something. Bringing awful powers into Ardenweald.\n\nIf you see any of their totems, destroy them immediately. \n\nI always feel better after smashing something to pieces, don't you?", progress = "What terrible magic has been brought into Ardenweald?", completion = "If it was not clear before, it is now. This is a personal hunt.\n\nWe will rid Ardenweald of this monster.", objectives = "Destroy Foul Totems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60631] = { id = 60631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Problem, Little Vorkai", description = "Ara'lon's report matches what I have seen. Too many enemies, and too few of the Wild Hunt to dispose of them on our own.\n\nFortunately, I feel strongly inclined to take matters into my own hands. And avenge my fallen hunters. \n\nLet us depart. We will show those monsters the fury of nature.", progress = "Ardenweald will endure.", completion = "We have slain so many, and yet more remain. We must get to the heart of this evil and tear it out.\n\nIf we don't, then soon it could spread all across Ardenweald.", objectives = "Slay Blighted with Korayn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60632] = { id = 60632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Know Your Face", description = "This voice... I have heard it before. Though it is distorted and vengeful now.\n\nHe hunts us.\n\nBut I am not prey. And I will not let him gloat over his slain quarry. That is not the way of the Wild Hunt.\n\nThough he may draw us to ground of his choosing, we will fight him.\n\nAnd we will win. Are you with me?", completion = "It cannot be easy for Korayn to hunt one of our own... but she is right. The forest is not safe so long as Lorkron lurks within it.\n\nWhat a terrible fate... both for those who become possessed, and those who must hunt them down.", objectives = "Defeat Lorkron the Hunter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60637] = { id = 60637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of Former Friends", description = "Heartwood Grove was to give up its anima so that other groves could survive.\n\nBut then... I started seeing these masks on many of the other fae. Soon, everyone was wearing them.\n\nI don't know what has come over them, but it's clear they mean us harm. Please... you have to...\n\nThey aren't the friends I once knew. Not anymore.", completion = "Thank you. I tried so hard to save them... but once that mask is on, there is no return.", objectives = "Slay 8 possessed creatures in Heartwood Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60638] = { id = 60638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recovering Wildseeds", description = "One of my tasks in Heartwood Grove was to tend to the wildseeds.\n\nSome were chosen to be brought back to Tirna Vaal. But now the masked fae are draining the anima from them!\n\nWe need to save the ones that remain. I beg of you, recover any surviving wildseeds you can find.\n\nThe spirits within them were chosen to be reborn. I won't let them wither away!", progress = "We need to split up and rescue as many wildseeds as we can.", completion = "You found more wildseeds! They're so weak... I can't stand to see them like this.\n\nWe need to finish this and bring them to Tirna Vaal as soon as possible.", objectives = "Recover 6 Drained wildseeds in the Heartwood Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60639] = { id = 60639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Grove", description = "We were supposed to take the heart of the grove to Tirna Vaal when we left this place to wither.\n\nThe masked fae struck before that could happen. They must be after the heart of the grove!\n\nThe heart contains all of the anima that was meant to save the other groves. We can't afford to lose it.\n\nCan you secure it? I need to find Korenth, one of our healers. His skills will help any survivors we find.", progress = "Do you have the heart of the grove?", completion = "Korenth is... gone? And the heart of the grove has been taken?\n\nThen... then we have much to do.", objectives = "Bring the Heart of the Grove to Tirna Vaal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60640] = { id = 60640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regrowth of the Grove", description = "The grove thrives, my mortal friend, but there is yet room for it to grow.\n\nWith enough anima, it can nourish even more wildseeds at once. Each one is a spirit that might otherwise be lost forever.\n\nSpeak with Zayhad once again, and see to the regrowth of the conservatory.", completion = "Your efforts revitalize the grove, and with it, countless spirits in need of aid.", objectives = "Upgrade the Queen's Conservatory to Tier Three.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60641] = { id = 60641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blossoming of the Grove", description = "The conservatory grows hearty and hale. Now, it must blossom anew.\n\nThough it requires much in the way of anima, every additional spirit that the conservatory rebirths returns your generosity tenfold.\n\nConfer with Zayhad, so that this conservatory may grow ever larger.", completion = "You have this grove's gratitude. Yet more spirits may now rejoin the cycle.", objectives = "Upgrade the Queen's Conservatory to Tier Four", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60642] = { id = 60642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grove Resplendent", description = "You have done much to return the conservatory to its former splendor.\n\nIn ages past, this grove was a place of convalescence for spirits who were wounded upon their demise, and needed special care before being reborn.\n\nIt was a place rarely used... but now, it is critical to the continuation of the cycle.\n\nTell Zayhad that the time has come. The Queen's Conservatory must thrive for the good of Ardenweald.", completion = "The conservatory, and the spirits who are tended here, are forever in your debt.\n\nThank you, Maw Walker.", objectives = "Upgrade the Queen's Conservatory to Tier Five", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60644] = { id = 60644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draw Out the Darkness", description = "Now that we have the dagger, it will take the combined will of all of us to sever the weapon's link to the High Chieftain. \n\nJaina, Anduin, and I must do our part to keep Baine's spirit grounded, so it will be up to you to deal with whatever force is unleashed when the blade is broken.\n\nAre you up to the task?", completion = "Were it not for your efforts, I am certain my body and soul would be trapped in this forsaken place for eternity.\n\nI owe you my life, {name}, and I will fight to my last breath to repay this debt.", objectives = "Draw out and defeat the Withering Presence in Detrithos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60645] = { id = 60645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gargantuan Seeker" }
quests[60646] = { id = 60646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Misery Business", description = "The Mawsworn have begun harvesting the misery of the souls flowing through Gorgoa, the river of souls.\n\nWhy? I do not know yet. But it behooves us to stop them.\n\nDestroy the conduits that they deposit the misery into and bring me some samples of their work. \n\nPerhaps with some research, I can discern their intentions.", progress = "Have you halted their misery?", completion = "Your burden is great, but today you have saved souls from damnation.", objectives = "Collect 10 Essences of Misery and destroy the Misery Conduits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60647] = { id = 60647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recovering the Animacones", description = "The grove's droman is wearing one of the masks. I fear he's going to drain all of the anima from the grove's heart!\n\nThat anima is meant for the forest's other groves. If we lose it... then Heartwood Grove would have been lost for nothing...\n\nWe'll carve a path to the Shrouded Mire to find the droman before it's too late.\n\nMany of these masked fae have stolen Heartwood Grove's animacones. We must recover them along the way. \n\nIn this drought, every bit of anima is precious.", progress = "We can't let the possessed take anything else from us.", completion = "So many animacones lost... at least we were able to recover these.", objectives = "Recover 25 animacones from the Possessed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60648] = { id = 60648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survivors of Heartwood Grove", description = "Korenth... I can't believe he's...\n\nWe have to save whomever we can. Droman Krelnor is too strong for us to face alone.\n\nI saw a few other survivors scattered around the grove. Hurry, we have no time to waste!", progress = "We must rescue my friends!", completion = "Derawyn... I can't lose her too! We can use the animacones to save her!", objectives = "Rescue Casad, Wagonmaster Derawyn, and Te'zan from the possessed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60649] = { id = 60649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thorn In Their Side" }
