quests[60659] = { id = 60659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Defense" }
quests[60660] = { id = 60660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight Test", description = "I fix these to my arms... then they become wings, yes?\n\nThen I jump off cliff. And fly!\n\nYou watch?", progress = "Did you watch me?", completion = "Hmm... did not work. What else, what else...", objectives = "Observe Kowalskos' test flight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60661] = { id = 60661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dying Dreams", description = "We have lost so much... and this one is special.\n\n<Moonberry looks at you, resolute. Her voice is strangely formal, her manner commanding.>\n\nCome, {name}. We will carry her on the Path of Rebirth and entreat the Queen to save her.\n\nHurry and make preparations. We have little time.", completion = "Well met, stranger. You arrive in... interesting times.\n\n<Herne snorts a laugh.>\n\nAnd with equally interesting company.", objectives = "Take Ysera's wildseed to the Heart of the Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60669] = { id = 60669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cause for Distraction", progress = "There is much to discuss.", completion = "Though we must search for Thrall and Baine, we cannot neglect the protection of our citizens and allies in the process.\n\nAs such, I have enlisted the aid of those who are experienced in dealing with the Scourge.", objectives = "Speak with Lor'themar Theron atop Grommash Hold in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60670] = { id = 60670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Crusade", description = "I have witnessed the relentless advance of the Scourge firsthand. It is only a matter of time before they swarm our gates. \n\nThe fate that befell Silvermoon must never be repeated. \n\nDeath knights from the Ebon Blade have stepped forward to combat the threat, but even they will need reinforcements.\n\nThe Argent Crusade has answered the call once more. I ask that you aid them in keeping our people safe, {name}.\n\nTheir commander awaits your arrival.", completion = "<Commander Throgg grunts.>\n\nYou must be the one.", objectives = "Speak with Commander Throgg in the Valley of Strength in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60671] = { id = 60671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sacrifices We Must Make", description = "Hurry! We can use the animacones we gathered to save Derawyn.\n\nI know they're intended for the wildseeds... but we can't let these monsters take anyone else from us.", completion = "The heart of the grove...\n\nWe have to get it back... for all those who have fallen.", objectives = "Use the recovered animacones to save Wagonmaster Derawyn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60673] = { id = 60673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Traitor", description = "Right, looks like I should let you in now.\n\nCan't promise Mateo will be too kind though. I prefer my old boss, but don't tell him that.\n\nWonder what happened to her. Denathrius seemed awfully upset when they last spoke.\n\nAnyways, let me just get that door open for ya.", progress = "Do you have Mateo's mirror shard?", completion = "He showed so much promise in his duties.\n\nI suppose the promise of power was too much for him to resist. But now is not the time to dwell on such things, {name}. Let us proceed.", objectives = "Kill Sinkeeper Mateo and collect his mirror shard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
